import postgres from 'postgres';

let client: ReturnType<typeof postgres> | null = null;

export function db() {
  if (!process.env.DATABASE_URL) throw new Error('DATABASE_URL is not set');
  if (!client) {
    const isLocal = process.env.DATABASE_URL.includes('localhost') || process.env.DATABASE_URL.includes('127.0.0.1');
    client = postgres(process.env.DATABASE_URL, {
      ssl: isLocal ? false : 'require',
      max: 5,
      idle_timeout: 20,
      // Recycle connections every few minutes so a socket left stale while the function was
      // frozen isn't reused (a query on it can hang).
      max_lifetime: 60 * 5,
      connect_timeout: 20,
      // No server-side prepared statements: a cached plan breaks with "cached plan must not
      // change result type" when a migration adds columns while connections are open, and
      // Neon's pooled connections don't keep them across transactions anyway.
      prepare: false,
    });
  }
  return client;
}
import { createHash, randomBytes } from 'crypto';
import { cookies } from 'next/headers';
import { db } from './db';

const COOKIE = 'pi_session';
const DAYS = 7;

function tokenHash([redacted] {
  return createHash('sha256').update(token).digest('hex');
}

export async function createSession(agentId: string) {
  const [redacted]
  const hash = tokenHash(token);
  const expires = new Date(Date.now() + DAYS * 86400_000);
  const sql = db();
  await sql`INSERT INTO sessions (token_hash, agent_id, expires_at) VALUES (${hash}, ${agentId}::uuid, ${expires})`;
  const jar = await cookies();
  jar.set(COOKIE, token, {
    httpOnly: true,
    sameSite: 'lax',
    secure: process.env.NODE_ENV === 'production',
    path: '/',
    expires,
  });
}

export async function destroySession() {
  const jar = await cookies();
  const [redacted]
  if (token) {
    const sql = db();
    await sql`DELETE FROM sessions WHERE token_hash = ${tokenHash(token)}`;
  }
  jar.set(COOKIE, '', { httpOnly: true, path: '/', expires: new Date(0) });
}

export async function currentAgent() {
  const jar = await cookies();
  const [redacted]
  if (!token) return null;
  const sql = db();
  const rows = await sql`
    SELECT a.id, a.name, a.username, a.role
    FROM sessions s
    JOIN agents a ON a.id = s.agent_id
    WHERE s.token_hash = ${tokenHash(token)}
      AND s.expires_at > now()
      AND a.active = TRUE
    LIMIT 1
  `;
  return rows[0] ?? null;
}

