import { timingSafeEqual } from 'crypto';
import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { currentUserAccess } from '@/lib/workspace-access';
import { loadOnboardingRoster,pickOnboarder,takeNextOnboarder } from '@/lib/onboarding';

// CleverTap (PPSL) webhook for the pic_subscription / payment_success event. Field sales reach the
// portal here in real time instead of the next day's Sub Raw sync:
//   - flow=subscribe and no onboarding case yet -> the case is created now, assigned through the
//     onboarding roster like any new case, with the employee code when CT sends one (optional).
//     Whichever comes first opens the case: seller Send to Onboarding, this webhook, or the next
//     day's Sub Raw sync; the others then leave it as is.
//   - a case already exists (seller handoff, earlier sync) -> nothing moves; the employee code is
//     added to it if it has none
//   - other flows (upgrade) -> only the event is stored
// Every event is also kept in ct_payment_events. Accepts CT's webhook body
// ({profiles:[{identity, key_values, event_properties, ...}]}), a single flat event, or an array.
// Merchant: customer_id (Cust ID) and/or mid (CT's profile identity is the MID; a MID alone is
// mapped to the Cust ID when the portal knows it, otherwise stored as unmatched_mid).
// Field names: flow / event_label, plan / event_label2,
// amount / event_label3, employee_code / event_label4, event_time (optional). Values sent as
// "flow=subscribe" are read as "subscribe".

function sameSecret(a:string,b:string){
  const aa=Buffer.from(a); const bb=Buffer.from(b);
  return aa.length===bb.length&&timingSafeEqual(aa,bb);
}

function val(v:unknown){
  let s=String(v??'').trim();
  if(/^[a-z_ ]+=/i.test(s)) s=s.slice(s.indexOf('=')+1).trim();
  // CT's liquid fallback (| default: "1") stands for a missing value, never a real one.
  if(s==='1') return null;
  return s||null;
}

function pick(srcs:any[],names:string[]){
  for(const src of srcs){
    if(!src||typeof src!=='object') continue;
    for(const n of names){
      if(src[n]!==undefined&&src[n]!==null&&String(src[n]).trim()!=='') return src[n];
    }
  }
  return undefined;
}

function eventTime(v:unknown){
  if(v===undefined||v===null||v==='') return null;
  const n=Number(v);
  // CT sends epoch seconds; also accept milliseconds and ISO strings.
  const d=Number.isFinite(n)?new Date(n<1e12?n*1000:n):new Date(String(v));
  return isNaN(d.getTime())?null:d;
}

function istDay(d:Date){
  return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
}

function normalize(item:any){
  const srcs=[item?.key_values,item?.event_properties,item?.eventProperties,item?.evtData,item?.profileData,item];
  // CT's profile identity is the MID; the Cust ID comes as its own field when CT sends it.
  const identity=val(pick(srcs,['identity']));
  const custRaw=val(pick(srcs,['customer_id','cust_id','custId','customerId','merchant_cust_id']))||(identity&&/^\d+$/.test(identity)?identity:null);
  const customerId=custRaw&&/^\d{5,}$/.test(custRaw)?custRaw:null; // real Cust IDs are 8+ digits
  const mid=val(pick(srcs,['mid','merchant_id','merchantId','MID']))||(identity&&!/^\d+$/.test(identity)?identity:null);
  if(!customerId&&!mid) return null;
  const amountRaw=val(pick(srcs,['amount','event_label3']));
  const amount=amountRaw&&Number.isFinite(Number(amountRaw.replace(/[^0-9.]/g,'')))&&amountRaw.replace(/[^0-9.]/g,'')!==''?Number(amountRaw.replace(/[^0-9.]/g,'')):null;
  const flow=val(pick(srcs,['flow','event_label']))?.toLowerCase()||null;
  const plan=val(pick(srcs,['plan','event_label2']))?.toLowerCase()||null;
  const employeeCode=val(pick(srcs,['employee_code','employeeCode','event_label4']));
  const category=val(pick(srcs,['category','event_category','payload_event_category']))?.toLowerCase()||null;
  const action=val(pick(srcs,['action','event_action','payload_event_action']))?.toLowerCase()||null;
  const at=eventTime(pick(srcs,['event_time','eventTime','ts','timestamp']))||new Date();
  // Only a subscription payment can open a case or set who sold it; top-ups, upgrades and
  // other payments are stored for the record. Category/action are checked when CT sends them.
  const isSubscription=flow==='subscribe'&&(!category||category==='pic_subscription')&&(!action||action==='payment_success');
  return {customerId,mid,flow,plan,amount,employeeCode,category,action,isSubscription,at,
    dedupeKey:[customerId||`mid:${mid}`,flow||'',plan||'',amount??'',istDay(at)].join('|'),raw:item};
}

export async function POST(req:Request){
  const configured=process.env.CT_WEBHOOK_SECRET||'';
  const supplied=req.headers.get('x-ct-webhook-secret')||'';
  const text=await req.text().catch(()=>'');
  // Refused calls are recorded (never the secret) so a CT setup problem shows up in the data.
  const reject=async(reason:string,status:number,error:string)=>{
    await db()`INSERT INTO ct_webhook_rejects(reason,body_excerpt) VALUES(${reason},${text.slice(0,2000)})`.catch(()=>{});
    return NextResponse.json({error},{status});
  };
  if(!configured||!supplied) return reject('missing_secret',401,'Unauthorized');
  if(!sameSecret(configured,supplied)) return reject('wrong_secret',401,'Unauthorized');
  let body:any=null;
  try{body=JSON.parse(text);}catch{}
  if(!body) return reject('invalid_json',400,'Invalid JSON');
  const items:any[]=Array.isArray(body)?body:Array.isArray(body.profiles)?body.profiles:Array.isArray(body.events)?body.events:[body];
  const rows=items.map(normalize).filter(Boolean) as NonNullable<ReturnType<typeof normalize>>[];
  const sql=db();
  let stored=0,created=0;
  for(const r of rows){
    // Only a MID: use the Cust ID the portal already knows for it (AdsRun Raw, earlier CT events).
    if(!r.customerId&&r.mid){
      const known=await sql`
        SELECT customer_id FROM merchant_ads WHERE mid=${r.mid} AND customer_id IS NOT NULL
        UNION ALL
        SELECT customer_id FROM ct_payment_events WHERE mid=${r.mid} AND customer_id IS NOT NULL
        LIMIT 1
      `;
      r.customerId=known[0]?.customer_id||null;
    }
    await sql.begin(async(tx:any)=>{
      await tx`SELECT pg_advisory_xact_lock(hashtext(${r.customerId||`mid:${r.mid}`}))`;
      const ins=await tx`
        INSERT INTO ct_payment_events(customer_id,mid,flow,plan,amount,employee_code,category,action,event_at,dedupe_key,raw)
        VALUES(${r.customerId},${r.mid},${r.flow},${r.plan},${r.amount},${r.employeeCode},${r.category},${r.action},${r.at},${r.dedupeKey},${sql.json(r.raw)})
        ON CONFLICT (dedupe_key) DO NOTHING
        RETURNING id
      `;
      if(!ins[0]) return; // CT retry: already handled
      stored++;
      if(!r.customerId){
        // MID the portal cannot map yet: kept for review; the next day's sync opens the case.
        await tx`UPDATE ct_payment_events SET case_action='unmatched_mid' WHERE id=${ins[0].id}`;
        return;
      }
      const existing=await tx`SELECT id,sold_by_employee_code FROM onboarding_cases WHERE customer_id=${r.customerId} ORDER BY created_at LIMIT 1 FOR UPDATE`;
      let action='ignored';
      if(existing[0]){
        action='existing';
        // Only the subscription sale sets who sold it; a later top-up never relabels the case.
        if(r.isSubscription&&r.employeeCode&&!existing[0].sold_by_employee_code)
          await tx`UPDATE onboarding_cases SET sold_by_employee_code=${r.employeeCode},updated_at=now() WHERE id=${existing[0].id}::uuid`;
      }else if(r.isSubscription){
        // Same equal rotation as every new onboarding case.
        const roster=await loadOnboardingRoster(tx);
        const target=roster.length?takeNextOnboarder(roster):await pickOnboarder();
        if(target){
          const saleDate=istDay(r.at);
          await tx`INSERT INTO customers(customer_id) VALUES(${r.customerId}) ON CONFLICT (customer_id) DO NOTHING`;
          const c=await tx`
            INSERT INTO onboarding_cases(customer_id,source_type,sale_date,assigned_to,assigned_at,last_activity_at,sold_by_employee_code,created_by_ct,rotation_agent_id)
            VALUES(${r.customerId},'historical_import',${saleDate}::date,${target.id}::uuid,now(),NULL,${r.employeeCode},TRUE,${target.id}::uuid)
            RETURNING id
          `;
          await tx`
            INSERT INTO onboarding_events(onboarding_case_id,customer_id,attempt_number,source_type,source_sheet,l0_code,l0_label_snapshot,remark)
            VALUES(${c[0].id}::uuid,${r.customerId},1,'assignment','CleverTap','SYSTEM_ASSIGNED','Assigned',
              ${`Assigned to ${target.name}: reported by CleverTap${r.employeeCode?` (employee ${r.employeeCode})`:''}`})
          `;
          action='created'; created++;
        }
      }
      await tx`UPDATE ct_payment_events SET case_action=${action} WHERE id=${ins[0].id}`;
    });
  }
  return NextResponse.json({ok:true,received:items.length,stored,casesCreated:created,duplicates:rows.length-stored,skipped:items.length-rows.length});
}

// Latest events, for admins to check the webhook is arriving.
export async function GET(){
  const user:any=await currentUserAccess();
  if(!user?.isSuperAdmin&&user?.role!=='admin') return NextResponse.json({error:'Admin only'},{status:403});
  const sql=db();
  const rows=await sql`
    SELECT customer_id,mid,flow,plan,amount::float8 AS amount,employee_code,case_action,event_at,received_at
    FROM ct_payment_events ORDER BY received_at DESC LIMIT 100
  `;
  return NextResponse.json({events:rows});
}
// CleverTap payments that arrived with only a MID (the merchant's CT profile had no Cust ID yet).
// Once the MID → Cust ID is known (Sub Raw's MID column in the daily onboarding sync, or AdsRun
// Raw), the event is linked to the Cust ID and, for a subscription, its employee code is put on
// that merchant's onboarding case if the case has none.
export async function linkCtPayments(sql:any,known:{mid:string;customer_id:string}[]){
  const ok=await sql`SELECT to_regclass('public.ct_payment_events') IS NOT NULL AS ok`;
  if(!ok[0]?.ok) return {linked:0,codes:0};
  const rows=await sql`
    WITH m AS (
      SELECT DISTINCT ON (mid) mid,customer_id FROM (
        SELECT x.mid,x.customer_id,1 AS pri FROM jsonb_to_recordset(${sql.json(known)}::jsonb) AS x(mid text,customer_id text)
        UNION ALL
        SELECT a.mid,a.customer_id,2 FROM merchant_ads a
        WHERE a.mid IS NOT NULL AND a.mid<>'' AND a.customer_id IS NOT NULL
          AND a.mid IN (SELECT mid FROM ct_payment_events WHERE customer_id IS NULL AND mid IS NOT NULL)
      ) s ORDER BY mid,pri
    ),
    l AS (
      UPDATE ct_payment_events e SET customer_id=m.customer_id,case_action='linked'
      FROM m WHERE e.customer_id IS NULL AND e.mid=m.mid
      RETURNING e.customer_id,e.employee_code,e.flow,e.category,e.action,e.received_at
    ),
    c AS (
      UPDATE onboarding_cases oc SET sold_by_employee_code=x.employee_code,updated_at=now()
      FROM (
        SELECT DISTINCT ON (customer_id) customer_id,employee_code FROM l
        WHERE employee_code IS NOT NULL AND flow='subscribe'
          AND (category IS NULL OR category='pic_subscription') AND (action IS NULL OR action='payment_success')
        ORDER BY customer_id,received_at
      ) x
      WHERE oc.customer_id=x.customer_id AND oc.sold_by_employee_code IS NULL
      RETURNING 1
    )
    SELECT (SELECT count(*)::int FROM l) AS linked,(SELECT count(*)::int FROM c) AS codes
  `;
  return {linked:Number(rows[0]?.linked||0),codes:Number(rows[0]?.codes||0)};
}

