  return Number(rows[0]?.n||1);
}
// Onboarding backlog rebalance, once a day at 8:30 AM IST.
//   Live team    = Onboarding team members with "New cases" on (onboarding_roster): they get new
//                  cases in real time.
//   Backlog team = everyone else on the Onboarding team (as in Teams; any onboarding access, active).
//   "No talk yet" = an open case from before today that was never called, or whose latest call is
//                  Not Connected, with no callback booked for later and never tagged Language Barrier.
// The live team's no-talk cases move to the backlog team, and the backlog team's no-talk cases are
// evened out so each person holds the same number, up to BACKLOG_CAP each. People keep their own
// cases first; only the excess moves, oldest-touched first going to whoever has the fewest. If the
// backlog team is full, the rest stay where they are. Each move is logged on the case.
import { todayIst } from './plans';

export const BACKLOG_CAP=10;

export async function rebalanceOnboardingBacklog(sql:any){
  const today=todayIst();
  const team=await sql`
    WITH m AS (
      SELECT DISTINCT ON (t.agent_id) t.agent_id,t.member FROM team_changes t
      WHERE t.team='onboarding' AND t.effective_from<=${today}::date ORDER BY t.agent_id,t.effective_from DESC,t.id DESC
    )
    SELECT a.id,a.name,EXISTS(SELECT 1 FROM onboarding_roster r WHERE r.agent_id=a.id) AS live
    FROM m JOIN agents a ON a.id=m.agent_id
    JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding'
    WHERE m.member AND a.active=TRUE
  `;
  const backlog=team.filter((p:any)=>!p.live).map((p:any)=>({id:String(p.id),name:p.name,cases:[] as any[]}));
  if(!backlog.length) return {moved:0,note:'No backlog team'};
  const liveIds=new Set(team.filter((p:any)=>p.live).map((p:any)=>String(p.id)));
  const cases=await sql`
    SELECT c.id,c.customer_id,c.assigned_to,COALESCE(c.last_activity_at,c.created_at) AS touched
    FROM onboarding_cases c
    LEFT JOIN LATERAL (
      SELECT e.l0_code FROM onboarding_events e
      WHERE e.onboarding_case_id=c.id AND e.source_type IN ('new_event','historical_import')
      ORDER BY e.event_time DESC,e.attempt_number DESC LIMIT 1
    ) last ON TRUE
    WHERE c.current_status='open' AND c.assigned_to IS NOT NULL
      AND (c.created_at AT TIME ZONE 'Asia/Kolkata')::date<${today}::date
      AND (last.l0_code IS NULL OR last.l0_code='OB_NOT_CONNECTED')
      AND (c.next_callback_at IS NULL OR c.next_callback_at<=now())
      -- Ever tagged Language Barrier: stays with its owner (who may speak the merchant's language).
      AND c.language_barrier_at IS NULL
      AND NOT EXISTS(SELECT 1 FROM onboarding_events lb WHERE lb.onboarding_case_id=c.id AND (lb.l1_code='OB_LANGUAGE_BARRIER' OR lb.l2_code='OB_LANGUAGE_BARRIER'))
    ORDER BY touched ASC
  `;
  const byId=new Map<string,any>(backlog.map((p:any)=>[p.id,p]));
  const pool:any[]=[];
  for(const c of cases){
    const owner=String(c.assigned_to);
    if(byId.has(owner)) byId.get(owner)!.cases.push(c);
    else if(liveIds.has(owner)) pool.push(c);
  }
  const total=pool.length+backlog.reduce((n:number,p:any)=>n+p.cases.length,0);
  const target=Math.min(BACKLOG_CAP,Math.ceil(total/backlog.length));
  // Excess over the target leaves its owner (most recently touched stays; oldest-touched moves).
  for(const p of backlog) while(p.cases.length>target) pool.push(p.cases.shift());
  pool.sort((a,b)=>new Date(a.touched).getTime()-new Date(b.touched).getTime());
  const moves:{c:any;to:any}[]=[];
  for(const c of pool){
    const to=[...backlog].sort((a,b)=>a.cases.length-b.cases.length||a.name.localeCompare(b.name))[0];
    if(to.cases.length>=target) break;
    to.cases.push(c);
    if(String(c.assigned_to)!==to.id) moves.push({c,to});
  }
  for(const {c,to} of moves){
    await sql.begin(async(tx:any)=>{
      const upd=await tx`UPDATE onboarding_cases SET assigned_to=${to.id}::uuid,assigned_at=now(),updated_at=now()
        WHERE id=${c.id} AND current_status='open' AND assigned_to=${c.assigned_to} RETURNING id`;
      if(!upd[0]) return;
      const n=(await tx`SELECT COALESCE(MAX(attempt_number),0)+1 AS n FROM onboarding_events WHERE onboarding_case_id=${c.id}`)[0].n;
      await tx`INSERT INTO onboarding_events(onboarding_case_id,customer_id,attempt_number,agent_name_raw,source_type,l0_code,l0_label_snapshot,remark)
        VALUES(${c.id},${c.customer_id},${n},'Backlog rebalance','assignment','SYSTEM_REASSIGNED','Reassigned',${`Reassigned to ${to.name} by the 8:30 AM backlog rebalance`})`;
    });
  }
  return {moved:moves.length,target,noTalkCases:total,backlogPeople:backlog.length,
    after:Object.fromEntries(backlog.map((p:any)=>[p.name,p.cases.length]))};
}

// Runs the day's once-a-day jobs that are due (called every 5 minutes by the lead sync trigger).
export async function runDailyJobs(sql:any){
  const ist=new Date(Date.now()+330*60000);
  const mins=ist.getUTCHours()*60+ist.getUTCMinutes();
  if(mins<8*60+30) return;
  const claim=await sql`INSERT INTO daily_jobs(job,run_date) VALUES('onboarding_backlog_rebalance',${todayIst()}::date) ON CONFLICT DO NOTHING RETURNING job`;
  if(!claim[0]) return;
  let result:any;
  try{ result=await rebalanceOnboardingBacklog(sql); }catch(e:any){ result={error:String(e?.message||e)}; console.error('backlog rebalance failed',e); }
  await sql`UPDATE daily_jobs SET result=${sql.json(result)} WHERE job='onboarding_backlog_rebalance' AND run_date=${todayIst()}::date`;
}
// Lead Gen Ads: Meta lead-form leads synced from the lead sheet.
//   - One lead per person: the sheet repeats rows (same Meta lead ID), and a person often submits
//     several times in a row; submissions from the same phone within 24 hours are one lead.
//   - A submission more than 24 hours after that phone's last lead is a new lead, tagged
//     "Repeat submission" (high intent), and goes through the rotation again.
//   - A lead a seller already called (a Seller disposition on its phone / Cust ID on or after the
//     day it came in) goes to that seller, tagged "Already called".
//   - Otherwise leads are shared round robin among the sellers switched on for Lead gen in
//     Manage Access (leadgen_roster), like the onboarding rotation. Switching someone off keeps
//     their leads with them; they just get no new ones.
//   - The phone is matched to a merchant (merchant sync) to get the Cust ID; until then the lead's
//     dispositions are saved against the lead, never with the phone as a Cust ID.

export type SheetLead={id?:string;created_time?:string;ad_name?:string;adset_name?:string;campaign_name?:string;form_name?:string;platform?:string;full_name?:string;phone_number?:string};

// A phone from the lead sheet ("p:[redacted]") as 10 digits.
export function leadPhone(raw:unknown){
  let d=String(raw??'').replace(/\D/g,'');
  if(d.length===12&&d.startsWith('91')) d=d.slice(2);
  else if(d.length===11&&d.startsWith('0')) d=d.slice(1);
  return d.length===10?d:null;
}

const clean=(v:unknown)=>{const s=String(v??'').trim();return s||null;};
const DAY=86400000;

export async function ingestLeads(sql:any,rows:SheetLead[]){
  const parsed=rows.map(r=>({meta:clean(String(r.id||'').replace(/^l:/,'')),phone:leadPhone(r.phone_number),at:new Date(String(r.created_time||'')),r}))
    .filter(x=>x.meta&&x.phone&&!Number.isNaN(x.at.getTime()))
    .sort((a,b)=>a.at.getTime()-b.at.getTime());
  const seen=new Set<string>();
  let created=0,merged=0,skipped=0;const newIds:string[]=[];
  for(const x of parsed){
    if(seen.has(x.meta!)){skipped++;continue;}
    seen.add(x.meta!);
    const known=await sql`SELECT 1 FROM leadgen_meta_ids WHERE meta_lead_id=${x.meta}`;
    if(known[0]){skipped++;continue;}
    const prev=(await sql`SELECT id,last_submitted_at FROM leadgen_leads WHERE phone=${x.phone} ORDER BY submitted_at DESC LIMIT 1`)[0];
    if(prev&&Math.abs(x.at.getTime()-new Date(prev.last_submitted_at).getTime())<DAY){
      await sql`UPDATE leadgen_leads SET submissions=submissions+1,last_submitted_at=GREATEST(last_submitted_at,${x.at.toISOString()}::timestamptz),
        name=COALESCE(name,${clean(x.r.full_name)}) WHERE id=${prev.id}`;
      await sql`INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES(${x.meta},${prev.id}) ON CONFLICT DO NOTHING`;
      merged++;continue;
    }
    const ins=await sql`
      INSERT INTO leadgen_leads(phone,name,submitted_at,last_submitted_at,campaign_name,adset_name,ad_name,form_name,platform,is_repeat)
      VALUES(${x.phone},${clean(x.r.full_name)},${x.at.toISOString()},${x.at.toISOString()},${clean(x.r.campaign_name)},${clean(x.r.adset_name)},
        ${clean(x.r.ad_name)},${clean(x.r.form_name)},${clean(x.r.platform)},${Boolean(prev)})
      RETURNING id
    `;
    await sql`INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES(${x.meta},${ins[0].id}) ON CONFLICT DO NOTHING`;
    newIds.push(String(ins[0].id));created++;
  }
  return {created,merged,skipped,newIds};
}

// Gives unlinked leads the Cust ID of the merchant with that phone, and moves their lead-only
// dispositions onto the Cust ID (attempt numbers continue after the merchant's own calls).
// Merchant phones only change with the daily merchant sync, so the 5-minute lead sync checks just
// the leads it brought in (onlyIds) and every unlinked lead is re-checked once after each merchant
// sync (linkAfterMerchantSync).
export async function linkLeadsToCustomers(sql:any,onlyIds?:string[]){
  if(onlyIds&&!onlyIds.length) return 0;
  const matches=await sql`
    SELECT l.id,l.phone,m.customer_id FROM leadgen_leads l
    JOIN LATERAL (
      SELECT customer_id FROM merchant_information
      WHERE active=TRUE AND right(regexp_replace(COALESCE(phone_number,''),'[^0-9]','','g'),10)=l.phone
      ORDER BY last_synced_at DESC NULLS LAST,customer_id LIMIT 1
    ) m ON TRUE
    WHERE l.customer_id IS NULL ${onlyIds?sql`AND l.id=ANY(${onlyIds}::uuid[])`:sql``}
  `;
  for(const x of matches){
    await sql.begin(async(tx:any)=>{
      await tx`SELECT pg_advisory_xact_lock(hashtext(${String(x.customer_id)}))`;
      await tx`INSERT INTO customers(customer_id) VALUES(${x.customer_id}) ON CONFLICT (customer_id) DO NOTHING`;
      await tx`UPDATE leadgen_leads SET customer_id=${x.customer_id} WHERE id=${x.id} AND customer_id IS NULL`;
      await tx`
        WITH base AS (SELECT COALESCE(max(attempt_number),0) AS n FROM calls WHERE customer_id=${x.customer_id}),
        moved AS (SELECT id,row_number() OVER (ORDER BY event_time,attempt_number) AS k FROM calls WHERE lead_id=${x.id} AND customer_id IS NULL)
        UPDATE calls c SET customer_id=${x.customer_id},attempt_number=(SELECT n FROM base)+moved.k,phone=COALESCE(c.phone,${x.phone})
        FROM moved WHERE c.id=moved.id
      `;
      await tx`UPDATE wa_messages SET customer_id=${x.customer_id} WHERE lead_id=${x.id} AND customer_id IS NULL`;
    });
  }
  return matches.length;
}

// Once per merchant sync: re-checks every unlinked lead against the new merchant phones. Called
// by the merchant sync itself and, as a safety net, by the 5-minute lead sync until it has run.
export async function linkAfterMerchantSync(sql:any){
  const run=(await sql`SELECT id FROM merchant_sync_runs WHERE status='success' AND leads_linked_at IS NULL
    AND started_at=(SELECT max(started_at) FROM merchant_sync_runs WHERE status='success')`)[0];
  if(!run) return 0;
  const n=await linkLeadsToCustomers(sql);
  await sql`UPDATE merchant_sync_runs SET leads_linked_at=now() WHERE id=${run.id}`;
  return n;
}

export async function loadLeadgenRoster(sql:any){
  const rows=await sql`
    WITH r AS (
      SELECT a.id,a.name,(SELECT max(added_at) FROM leadgen_roster) AS since
      FROM leadgen_roster o JOIN agents a ON a.id=o.agent_id
      JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='seller'
      WHERE a.active=TRUE
    )
    SELECT r.id,r.name,
      (SELECT count(*)::int FROM leadgen_leads l WHERE l.rotation_agent_id=r.id AND l.assigned_at>=r.since) AS count,
      (SELECT max(l.assigned_at) FROM leadgen_leads l WHERE l.rotation_agent_id=r.id) AS last
    FROM r ORDER BY r.name
  `;
  return rows.map((x:any)=>({id:String(x.id),name:x.name,count:Number(x.count),last:x.last?new Date(x.last).getTime():0}));
}

// Assigns every unassigned lead, oldest first: to the seller who already called it, else the
// next seller in the Lead gen rotation. With nobody switched on, leads wait unassigned.
export async function assignUnassignedLeads(sql:any){
  const leads=await sql`SELECT id,phone,customer_id,submitted_at FROM leadgen_leads WHERE assigned_to IS NULL ORDER BY submitted_at`;
  if(!leads.length) return 0;
  const roster=await loadLeadgenRoster(sql);
  let n=0;
  for(const l of leads){
    const caller=(await sql`
      SELECT c.agent_id FROM calls c
      WHERE c.source_type='new_call' AND c.agent_id IS NOT NULL
        AND (c.lead_id=${l.id} OR c.customer_id=${l.phone} OR (${l.customer_id}::text IS NOT NULL AND c.customer_id=${l.customer_id}))
        AND c.call_date>=(${l.submitted_at}::timestamptz AT TIME ZONE 'Asia/Kolkata')::date
      ORDER BY c.event_time DESC NULLS LAST LIMIT 1
    `)[0];
    if(caller){
      await sql`UPDATE leadgen_leads SET assigned_to=${caller.agent_id},assigned_at=now(),already_called=TRUE WHERE id=${l.id} AND assigned_to IS NULL`;
      n++;continue;
    }
    if(!roster.length) continue;
    const next=[...roster].sort((a,b)=>(a.count-b.count)||(a.last-b.last)||a.name.localeCompare(b.name))[0];
    next.count++; next.last=Date.now();
    await sql`UPDATE leadgen_leads SET assigned_to=${next.id}::uuid,rotation_agent_id=${next.id}::uuid,assigned_at=now() WHERE id=${l.id} AND assigned_to IS NULL`;
    n++;
  }
  return n;
}
// Subscription plans sold from 1 Oct 2026. Prices exclude GST; revenue is always ex-GST.
export const PLANS = {
  silver: { label: 'Silver', price: 1999 },
  gold: { label: 'Gold', price: 4999 },
  platinum: { label: 'Platinum', price: 9999 },
} as const;
export type PlanCode = keyof typeof PLANS;

export const PLAN_START_DATE = '2026-10-01';
// Every sale before plans were introduced was the ₹799 subscription.
export const LEGACY_SALE_PRICE = 799;

export function isPlanCode(v: unknown): v is PlanCode {
  return typeof v === 'string' && Object.prototype.hasOwnProperty.call(PLANS, v);
}

export function plansRequiredOn(date: string) {
  return date >= PLAN_START_DATE;
}

// Revenue of one sale dated `date`. Before 1 Oct every sale is ₹799; from 1 Oct it is the
// plan price stored on the sale (0 if none was recorded).
export function saleRevenue(date: string, planAmount: number | null | undefined) {
  if (!plansRequiredOn(date)) return LEGACY_SALE_PRICE;
  return Number(planAmount || 0);
}

export function todayIst() {
  return new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
}

// Last 10 digits of a phone number, or null when there are fewer than 10 digits.
export function phoneKey(v: unknown) {
  const digits = String(v ?? '').replace(/\D/g, '');
  return digits.length >= 10 ? digits.slice(-10) : null;
}

// Plan upgrades. A merchant's plan before plans existed is the legacy ₹799 subscription (₹499 is
// only its renewal price, so upgrades are always valued from ₹799).
export type CurrentPlan = 'legacy' | PlanCode;
export const PLAN_RANK: Record<CurrentPlan, number> = { legacy: 0, silver: 1, gold: 2, platinum: 3 };
export function planPrice(p: CurrentPlan) {
  return p === 'legacy' ? LEGACY_SALE_PRICE : PLANS[p].price;
}
export function planLabel(p: CurrentPlan) {
  return p === 'legacy' ? `₹${LEGACY_SALE_PRICE} plan` : PLANS[p].label;
}
// Plans a merchant on `from` can upgrade to (only higher plans).
export function upgradeTargets(from: CurrentPlan): PlanCode[] {
  return (Object.keys(PLANS) as PlanCode[]).filter(p => PLAN_RANK[p] > PLAN_RANK[from]);
}
// Upgrade value credited for incentives: new plan price minus current plan price.
export function upgradeValue(from: CurrentPlan, to: PlanCode) {
  return Math.max(0, PLANS[to].price - planPrice(from));
}
// Sub Raw plan name → plan ("₹799 Plan" / "₹499 Plan" → legacy).
export function planFromName(name: unknown): CurrentPlan | null {
  const n = String(name ?? '').toLowerCase();
  if (!n) return null;
  for (const p of Object.keys(PLANS) as PlanCode[]) if (n.includes(PLANS[p].label.toLowerCase())) return p;
  if (/799|499/.test(n)) return 'legacy';
  return null;
}
export function isCurrentPlan(v: unknown): v is CurrentPlan {
  return v === 'legacy' || isPlanCode(v);
}
// CSM workspace: merchants whose ads have gone live, worked by Customer Success Managers.
//
// Built from the latest completed SMB Daily Tracker sync (Sub Raw + AdsRun Raw). A merchant is
// in the CSM queues when their ads have run (rows in AdsRun Raw, or completed_ads_count > 0 in
// Sub Raw). Every merchant lands in exactly one queue, checked in this order:
//   onb_lost  — onboarding closed the case as Not Interested / Refund (shown for context, any ads)
//   cancelled — subscription still ACTIVE but the merchant has cancelled (cancelled_at set)
//   lapsed    — subscription CANCELLED or EXPIRED
//   ending    — subscription active, an ad running now
//   ended     — subscription active, no ad running
// A merchant whose latest CSM call is Not Interested / Refund moves to "closed" until a CSM
// logs something else.
// Merchants whose onboarding case the Sub Raw sync reopened (no ad ran, or the ad failed) stay
// with onboarding and are left out until the first ad is properly live.

export const CSM_L0_CODES = ['OB_IN_PROCESS','OB_NOT_CONNECTED','OB_ADDITIONAL_TOPUP','OB_PLAN_UPGRADED','OB_ANOTHER_AD_LIVE','OB_CREATIVE_UPDATED','OB_SUBS_RENEWED','OB_NOT_INTERESTED','OB_REFUND_REQUESTED'];
export const CSM_CLOSING_CODES = ['OB_NOT_INTERESTED','OB_REFUND_REQUESTED'];
export type CsmQueue = 'ending'|'ended'|'cancelled'|'lapsed'|'onb_lost';
export const CSM_BUCKETS = ['ending','ended','cancelled','lapsed','closed','onb_lost'];

export async function latestCompleteRun(sql:any):Promise<{id:number;finished_at:string;subs_rows:number;ads_rows:number}|null>{
  const ok=await sql`SELECT to_regclass('public.csm_sync_runs') IS NOT NULL AS ok`;
  if(!ok[0]?.ok) return null;
  const rows=await sql`SELECT id,finished_at,subs_rows,ads_rows FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 1`;
  return rows[0]||null;
}

// Every merchant in the CSM workspace with everything the queue and detail views need.
export async function csmMerchants(sql:any,runId:number){
  return sql`
    WITH subs AS (
      SELECT * FROM merchant_subscriptions WHERE sync_run_id=${runId}
    ), ads AS (
      SELECT customer_id,count(*)::int AS total_ads,
        count(*) FILTER (WHERE ad_status='ACTIVE')::int AS active_ads,
        count(*) FILTER (WHERE ad_status='COMPLETED')::int AS completed_ads,
        max(merchant_name) AS ad_merchant_name,max(phone_number) AS ad_phone
      FROM merchant_ads WHERE sync_run_id=${runId} GROUP BY customer_id
    ), cases AS (
      SELECT DISTINCT ON (customer_id) id,customer_id,current_status,assigned_to,ads_live_at,closed_at,current_l0,current_l1,current_l2,reopen_reason
      FROM onboarding_cases ORDER BY customer_id,created_at
    ), base AS (
      SELECT s.customer_id,s.status AS sub_status,
        COALESCE(NULLIF(s.merchant_name,''),a.ad_merchant_name) AS merchant_name,
        COALESCE(NULLIF(s.phone_number,''),a.ad_phone) AS phone_number,
        s.category,s.sub_category,s.mcc,s.sub_first_date,
        s.cancelled_at::text AS cancelled_at,s.expected_renewal_due_date::text AS renewal_due,s.renewal_date::text AS renewal_date,
        s.completed_ads_count,s.wallet_balance::float8 AS credits,
        COALESCE(a.total_ads,0) AS total_ads,COALESCE(a.active_ads,0) AS active_ads,COALESCE(a.completed_ads,0) AS completed_ads,
        c.id AS case_id,c.current_status AS case_status,owner.name AS onboarding_owner,
        CASE WHEN c.current_status='lost' THEN concat_ws(' → ',c.current_l0,c.current_l1,c.current_l2) END AS lost_reason,
        CASE WHEN c.current_status='lost' THEN c.closed_at END AS lost_at,
        CASE WHEN c.current_status='lost' THEN 'onb_lost'
             WHEN upper(COALESCE(NULLIF(s.check_sub_status,''),s.status))='ACTIVE' AND s.cancelled_at IS NOT NULL THEN 'cancelled'
             WHEN s.status IN ('CANCELLED','EXPIRED') THEN 'lapsed'
             WHEN COALESCE(a.active_ads,0)>0 THEN 'ending'
             ELSE 'ended' END AS queue
      FROM subs s
      LEFT JOIN ads a ON a.customer_id=s.customer_id
      LEFT JOIN cases c ON c.customer_id=s.customer_id
      LEFT JOIN agents owner ON owner.id=c.assigned_to
      WHERE (c.current_status='lost' OR COALESCE(a.total_ads,0)>0 OR COALESCE(s.completed_ads_count,0)>0)
        -- Reopened by the onboarding sync (no ad ran / ad failed): onboarding owns them until the first ad is live.
        AND NOT (c.current_status='open' AND c.reopen_reason IS NOT NULL)
    ), cs AS (
      SELECT e.customer_id,e.event_time,e.l0_code,e.l0_label_snapshot,e.l1_label_snapshot,e.l2_label_snapshot,e.remark,e.callback_at,e.agent_name_raw,
        row_number() OVER (PARTITION BY e.customer_id ORDER BY e.event_time DESC,e.attempt_number DESC) AS rn
      FROM onboarding_events e
      WHERE e.source_type='customer_success_followup' AND e.customer_id IN (SELECT customer_id FROM base)
    ), cs_agg AS (
      SELECT customer_id,max(event_time) AS last_outreach,
        max(event_time) FILTER (WHERE l0_code<>'OB_NOT_CONNECTED') AS last_connect,
        count(*)::int AS cs_calls
      FROM cs GROUP BY customer_id
    ), money AS (
      SELECT e.customer_id,
        count(*) FILTER (WHERE (e.l0_code='OB_ADDITIONAL_TOPUP' AND e.top_up_amount_inr>0) OR (e.l0_code='OB_PLAN_UPGRADED' AND e.upgrade_value_inr>0))::int AS topups,
        COALESCE(sum(COALESCE(e.top_up_amount_inr,e.upgrade_value_inr)) FILTER (WHERE e.l0_code IN ('OB_ADDITIONAL_TOPUP','OB_PLAN_UPGRADED')),0)::float8 AS topup_total,
        count(*) FILTER (WHERE e.l0_code='OB_SUBS_RENEWED')::int AS renewals,
        (array_agg(e.plan_code ORDER BY e.event_time DESC) FILTER (WHERE e.l0_code='OB_SUBS_RENEWED'))[1] AS last_renewal_plan
      FROM onboarding_events e WHERE e.customer_id IN (SELECT customer_id FROM base)
      GROUP BY e.customer_id
    ), pitch AS (
      SELECT DISTINCT ON (customer_id) customer_id,note,note_date::text AS note_date,author_name
      FROM csm_notes WHERE kind='pitch' ORDER BY customer_id,note_date DESC,id DESC
    ), sheet_remark AS (
      SELECT DISTINCT ON (customer_id) customer_id,note,note_date::text AS note_date,author_name
      FROM csm_notes WHERE kind='sheet_remark' ORDER BY customer_id,note_date DESC,id DESC
    )
    SELECT b.*,
      sel.creative_name,sel.description,sel.ad_status,sel.budget::float8 AS budget,sel.start_date::text AS start_date,sel.end_date::text AS end_date,
      sel.impressions::float8 AS impressions,sel.clicks::float8 AS clicks,sel.ctr::float8 AS ctr,sel.reach::float8 AS reach,sel.spend::float8 AS spend,
      asg.agent_id AS assigned_to,ag.name AS assigned_name,
      p.note AS pitch,p.note_date AS pitch_date,p.author_name AS pitch_by,
      sr.note AS sheet_remark,sr.note_date AS sheet_remark_date,
      ca.last_outreach,ca.last_connect,COALESCE(ca.cs_calls,0) AS cs_calls,
      lc.l0_code AS last_l0_code,lc.l0_label_snapshot AS last_l0,lc.l1_label_snapshot AS last_l1,lc.l2_label_snapshot AS last_l2,
      lc.remark AS last_remark,lc.agent_name_raw AS last_by,lc.callback_at AS next_callback,
      (b.queue<>'onb_lost' AND COALESCE(lc.l0_code IN ('OB_NOT_INTERESTED','OB_REFUND_REQUESTED'),FALSE)) AS closed,
      COALESCE(m.topups,0) AS topups,COALESCE(m.topup_total,0) AS topup_total,COALESCE(m.renewals,0) AS renewals,m.last_renewal_plan
    FROM base b
    LEFT JOIN LATERAL (
      SELECT * FROM merchant_ads x WHERE x.sync_run_id=${runId} AND x.customer_id=b.customer_id
      ORDER BY
        CASE WHEN b.queue='ending' AND x.ad_status='ACTIVE' THEN 0 WHEN b.queue<>'ending' AND x.ad_status='COMPLETED' THEN 0 ELSE 1 END,
        CASE WHEN b.queue='ending' THEN x.end_date END ASC NULLS LAST,
        CASE WHEN b.queue<>'ending' THEN x.end_date END DESC NULLS LAST,
        x.clicks DESC NULLS LAST,
        x.end_date DESC NULLS LAST,
        x.source_row
      LIMIT 1
    ) sel ON TRUE
    LEFT JOIN csm_assignments asg ON asg.customer_id=b.customer_id
    LEFT JOIN agents ag ON ag.id=asg.agent_id
    LEFT JOIN pitch p ON p.customer_id=b.customer_id
    LEFT JOIN sheet_remark sr ON sr.customer_id=b.customer_id
    LEFT JOIN cs_agg ca ON ca.customer_id=b.customer_id
    LEFT JOIN cs lc ON lc.customer_id=b.customer_id AND lc.rn=1
    LEFT JOIN money m ON m.customer_id=b.customer_id
  `;
}

// Default order inside each queue. The CSM screen can re-sort by impressions, spend or credits.
//   cancelled — most credits first
//   lapsed    — most recently due for renewal first (yesterday, D-2, ...), then most credits
//   ending    — most impressions, then most spend
//   ended     — most credits, then most impressions
//   onb_lost  — most recently lost first
export function sortQueue(rows:any[]){
  const t=(d:any)=>d?new Date(d).getTime():0;
  const n=(v:any)=>Number(v)||0;
  const qOrder:any={ending:0,ended:1,cancelled:2,lapsed:3,onb_lost:4};
  return [...rows].sort((a,b)=>{
    if(a.queue!==b.queue) return qOrder[a.queue]-qOrder[b.queue];
    if(a.queue==='cancelled') return (n(b.credits)-n(a.credits))||(n(b.impressions)-n(a.impressions));
    if(a.queue==='lapsed') return (t(b.renewal_due)-t(a.renewal_due))||(n(b.credits)-n(a.credits));
    if(a.queue==='ending') return (n(b.impressions)-n(a.impressions))||(n(b.spend)-n(a.spend));
    if(a.queue==='ended') return (n(b.credits)-n(a.credits))||(n(b.impressions)-n(a.impressions));
    return t(b.lost_at)-t(a.lost_at);
  });
}

