75	// Onboarding backlog rebalance, once a day at 8:30 AM IST.
76	//   Live team    = Onboarding team members with "New cases" on (onboarding_roster): they get new
77	//                  cases in real time.
78	//   Backlog team = everyone else on the Onboarding team (as in Teams; any onboarding access, active).
79	//   "No talk yet" = an open case from before today that was never called, or whose latest call is
80	//                  Not Connected, with no callback booked for later and never tagged Language Barrier.
81	// The live team's no-talk cases move to the backlog team, and the backlog team's no-talk cases are
82	// evened out so each person holds the same number, up to BACKLOG_CAP each. People keep their own
83	// cases first; only the excess moves, oldest-touched first going to whoever has the fewest. If the
84	// backlog team is full, the rest stay where they are. Each move is logged on the case.
85	import { todayIst } from './plans';
86	
87	export const BACKLOG_CAP=10;
88	
89	export async function rebalanceOnboardingBacklog(sql:any){
90	  const today=todayIst();
91	  const team=await sql`
92	    WITH m AS (
93	      SELECT DISTINCT ON (t.agent_id) t.agent_id,t.member FROM team_changes t
94	      WHERE t.team='onboarding' AND t.effective_from<=${today}::date ORDER BY t.agent_id,t.effective_from DESC,t.id DESC
95	    )
96	    SELECT a.id,a.name,EXISTS(SELECT 1 FROM onboarding_roster r WHERE r.agent_id=a.id) AS live
97	    FROM m JOIN agents a ON a.id=m.agent_id
98	    JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding'
99	    WHERE m.member AND a.active=TRUE
100	  `;
101	  const backlog=team.filter((p:any)=>!p.live).map((p:any)=>({id:String(p.id),name:p.name,cases:[] as any[]}));
102	  if(!backlog.length) return {moved:0,note:'No backlog team'};
103	  const liveIds=new Set(team.filter((p:any)=>p.live).map((p:any)=>String(p.id)));
104	  const cases=await sql`
105	    SELECT c.id,c.customer_id,c.assigned_to,COALESCE(c.last_activity_at,c.created_at) AS touched
106	    FROM onboarding_cases c
107	    LEFT JOIN LATERAL (
108	      SELECT e.l0_code FROM onboarding_events e
109	      WHERE e.onboarding_case_id=c.id AND e.source_type IN ('new_event','historical_import')
110	      ORDER BY e.event_time DESC,e.attempt_number DESC LIMIT 1
111	    ) last ON TRUE
112	    WHERE c.current_status='open' AND c.assigned_to IS NOT NULL
113	      AND (c.created_at AT TIME ZONE 'Asia/Kolkata')::date<${today}::date
114	      AND (last.l0_code IS NULL OR last.l0_code='OB_NOT_CONNECTED')
115	      AND (c.next_callback_at IS NULL OR c.next_callback_at<=now())
116	      -- Ever tagged Language Barrier: stays with its owner (who may speak the merchant's language).
117	      AND c.language_barrier_at IS NULL
118	      AND NOT EXISTS(SELECT 1 FROM onboarding_events lb WHERE lb.onboarding_case_id=c.id AND (lb.l1_code='OB_LANGUAGE_BARRIER' OR lb.l2_code='OB_LANGUAGE_BARRIER'))
119	    ORDER BY touched ASC
120	  `;
121	  const byId=new Map<string,any>(backlog.map((p:any)=>[p.id,p]));
122	  const pool:any[]=[];
123	  for(const c of cases){
124	    const owner=String(c.assigned_to);
125	    if(byId.has(owner)) byId.get(owner)!.cases.push(c);
126	    else if(liveIds.has(owner)) pool.push(c);
127	  }
128	  const total=pool.length+backlog.reduce((n:number,p:any)=>n+p.cases.length,0);
129	  const target=Math.min(BACKLOG_CAP,Math.ceil(total/backlog.length));
130	  // Excess over the target leaves its owner (most recently touched stays; oldest-touched moves).
131	  for(const p of backlog) while(p.cases.length>target) pool.push(p.cases.shift());
132	  pool.sort((a,b)=>new Date(a.touched).getTime()-new Date(b.touched).getTime());
133	  const moves:{c:any;to:any}[]=[];
134	  for(const c of pool){
135	    const to=[...backlog].sort((a,b)=>a.cases.length-b.cases.length||a.name.localeCompare(b.name))[0];
136	    if(to.cases.length>=target) break;
137	    to.cases.push(c);
138	    if(String(c.assigned_to)!==to.id) moves.push({c,to});
139	  }
140	  for(const {c,to} of moves){
141	    await sql.begin(async(tx:any)=>{
142	      const upd=await tx`UPDATE onboarding_cases SET assigned_to=${to.id}::uuid,assigned_at=now(),updated_at=now()
143	        WHERE id=${c.id} AND current_status='open' AND assigned_to=${c.assigned_to} RETURNING id`;
144	      if(!upd[0]) return;
145	      const n=(await tx`SELECT COALESCE(MAX(attempt_number),0)+1 AS n FROM onboarding_events WHERE onboarding_case_id=${c.id}`)[0].n;
146	      await tx`INSERT INTO onboarding_events(onboarding_case_id,customer_id,attempt_number,agent_name_raw,source_type,l0_code,l0_label_snapshot,remark)
147	        VALUES(${c.id},${c.customer_id},${n},'Backlog rebalance','assignment','SYSTEM_REASSIGNED','Reassigned',${`Reassigned to ${to.name} by the 8:30 AM backlog rebalance`})`;
148	    });
149	  }
150	  return {moved:moves.length,target,noTalkCases:total,backlogPeople:backlog.length,
151	    after:Object.fromEntries(backlog.map((p:any)=>[p.name,p.cases.length]))};
152	}
