164	}
165	// Lead Gen Ads: Meta lead-form leads synced from the lead sheet.
166	//   - One lead per person: the sheet repeats rows (same Meta lead ID), and a person often submits
167	//     several times in a row; submissions from the same phone within 24 hours are one lead.
168	//   - A submission more than 24 hours after that phone's last lead is a new lead, tagged
169	//     "Repeat submission" (high intent), and goes through the rotation again.
170	//   - A lead a seller already called (a Seller disposition on its phone / Cust ID on or after the
171	//     day it came in) goes to that seller, tagged "Already called".
172	//   - Otherwise leads are shared round robin among the sellers switched on for Lead gen in
173	//     Manage Access (leadgen_roster), like the onboarding rotation. Switching someone off keeps
174	//     their leads with them; they just get no new ones.
175	//   - The phone is matched to a merchant (merchant sync) to get the Cust ID; until then the lead's
176	//     dispositions are saved against the lead, never with the phone as a Cust ID.
177	
178	export type SheetLead={id?:string;created_time?:string;ad_name?:string;adset_name?:string;campaign_name?:string;form_name?:string;platform?:string;full_name?:string;phone_number?:string};
179	
180	// A phone from the lead sheet ("p:[redacted]") as 10 digits.
181	export function leadPhone(raw:unknown){
182	  let d=String(raw??'').replace(/\D/g,'');
183	  if(d.length===12&&d.startsWith('91')) d=d.slice(2);
184	  else if(d.length===11&&d.startsWith('0')) d=d.slice(1);
185	  return d.length===10?d:null;
186	}
