188	const clean=(v:unknown)=>{const s=String(v??'').trim();return s||null;};
189	const DAY=86400000;
190	
191	export async function ingestLeads(sql:any,rows:SheetLead[]){
192	  const parsed=rows.map(r=>({meta:clean(String(r.id||'').replace(/^l:/,'')),phone:leadPhone(r.phone_number),at:new Date(String(r.created_time||'')),r}))
193	    .filter(x=>x.meta&&x.phone&&!Number.isNaN(x.at.getTime()))
194	    .sort((a,b)=>a.at.getTime()-b.at.getTime());
195	  const seen=new Set<string>();
196	  let created=0,merged=0,skipped=0;const newIds:string[]=[];
197	  for(const x of parsed){
198	    if(seen.has(x.meta!)){skipped++;continue;}
199	    seen.add(x.meta!);
200	    const known=await sql`SELECT 1 FROM leadgen_meta_ids WHERE meta_lead_id=${x.meta}`;
201	    if(known[0]){skipped++;continue;}
202	    const prev=(await sql`SELECT id,last_submitted_at FROM leadgen_leads WHERE phone=${x.phone} ORDER BY submitted_at DESC LIMIT 1`)[0];
203	    if(prev&&Math.abs(x.at.getTime()-new Date(prev.last_submitted_at).getTime())<DAY){
204	      await sql`UPDATE leadgen_leads SET submissions=submissions+1,last_submitted_at=GREATEST(last_submitted_at,${x.at.toISOString()}::timestamptz),
205	        name=COALESCE(name,${clean(x.r.full_name)}) WHERE id=${prev.id}`;
206	      await sql`INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES(${x.meta},${prev.id}) ON CONFLICT DO NOTHING`;
207	      merged++;continue;
208	    }
209	    const ins=await sql`
210	      INSERT INTO leadgen_leads(phone,name,submitted_at,last_submitted_at,campaign_name,adset_name,ad_name,form_name,platform,is_repeat)
211	      VALUES(${x.phone},${clean(x.r.full_name)},${x.at.toISOString()},${x.at.toISOString()},${clean(x.r.campaign_name)},${clean(x.r.adset_name)},
212	        ${clean(x.r.ad_name)},${clean(x.r.form_name)},${clean(x.r.platform)},${Boolean(prev)})
213	      RETURNING id
214	    `;
215	    await sql`INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES(${x.meta},${ins[0].id}) ON CONFLICT DO NOTHING`;
216	    newIds.push(String(ins[0].id));created++;
217	  }
218	  return {created,merged,skipped,newIds};
219	}
