221	// Gives unlinked leads the Cust ID of the merchant with that phone, and moves their lead-only
222	// dispositions onto the Cust ID (attempt numbers continue after the merchant's own calls).
223	// Merchant phones only change with the daily merchant sync, so the 5-minute lead sync checks just
224	// the leads it brought in (onlyIds) and every unlinked lead is re-checked once after each merchant
225	// sync (linkAfterMerchantSync).
226	export async function linkLeadsToCustomers(sql:any,onlyIds?:string[]){
227	  if(onlyIds&&!onlyIds.length) return 0;
228	  const matches=await sql`
229	    SELECT l.id,l.phone,m.customer_id FROM leadgen_leads l
230	    JOIN LATERAL (
231	      SELECT customer_id FROM merchant_information
232	      WHERE active=TRUE AND right(regexp_replace(COALESCE(phone_number,''),'[^0-9]','','g'),10)=l.phone
233	      ORDER BY last_synced_at DESC NULLS LAST,customer_id LIMIT 1
234	    ) m ON TRUE
235	    WHERE l.customer_id IS NULL ${onlyIds?sql`AND l.id=ANY(${onlyIds}::uuid[])`:sql``}
236	  `;
237	  for(const x of matches){
238	    await sql.begin(async(tx:any)=>{
239	      await tx`SELECT pg_advisory_xact_lock(hashtext(${String(x.customer_id)}))`;
240	      await tx`INSERT INTO customers(customer_id) VALUES(${x.customer_id}) ON CONFLICT (customer_id) DO NOTHING`;
241	      await tx`UPDATE leadgen_leads SET customer_id=${x.customer_id} WHERE id=${x.id} AND customer_id IS NULL`;
242	      await tx`
243	        WITH base AS (SELECT COALESCE(max(attempt_number),0) AS n FROM calls WHERE customer_id=${x.customer_id}),
244	        moved AS (SELECT id,row_number() OVER (ORDER BY event_time,attempt_number) AS k FROM calls WHERE lead_id=${x.id} AND customer_id IS NULL)
245	        UPDATE calls c SET customer_id=${x.customer_id},attempt_number=(SELECT n FROM base)+moved.k,phone=COALESCE(c.phone,${x.phone})
246	        FROM moved WHERE c.id=moved.id
247	      `;
248	      await tx`UPDATE wa_messages SET customer_id=${x.customer_id} WHERE lead_id=${x.id} AND customer_id IS NULL`;
249	    });
250	  }
251	  return matches.length;
252	}
