281	// Assigns every unassigned lead, oldest first: to the seller who already called it, else the
282	// next seller in the Lead gen rotation. With nobody switched on, leads wait unassigned.
283	export async function assignUnassignedLeads(sql:any){
284	  const leads=await sql`SELECT id,phone,customer_id,submitted_at FROM leadgen_leads WHERE assigned_to IS NULL ORDER BY submitted_at`;
285	  if(!leads.length) return 0;
286	  const roster=await loadLeadgenRoster(sql);
287	  let n=0;
288	  for(const l of leads){
289	    const caller=(await sql`
290	      SELECT c.agent_id FROM calls c
291	      WHERE c.source_type='new_call' AND c.agent_id IS NOT NULL
292	        AND (c.lead_id=${l.id} OR c.customer_id=${l.phone} OR (${l.customer_id}::text IS NOT NULL AND c.customer_id=${l.customer_id}))
293	        AND c.call_date>=(${l.submitted_at}::timestamptz AT TIME ZONE 'Asia/Kolkata')::date
294	      ORDER BY c.event_time DESC NULLS LAST LIMIT 1
295	    `)[0];
296	    if(caller){
297	      await sql`UPDATE leadgen_leads SET assigned_to=${caller.agent_id},assigned_at=now(),already_called=TRUE WHERE id=${l.id} AND assigned_to IS NULL`;
298	      n++;continue;
299	    }
300	    if(!roster.length) continue;
301	    const next=[...roster].sort((a,b)=>(a.count-b.count)||(a.last-b.last)||a.name.localeCompare(b.name))[0];
302	    next.count++; next.last=Date.now();
303	    await sql`UPDATE leadgen_leads SET assigned_to=${next.id}::uuid,rotation_agent_id=${next.id}::uuid,assigned_at=now() WHERE id=${l.id} AND assigned_to IS NULL`;
304	    n++;
305	  }
306	  return n;
307	}
308	// Subscription plans sold from 1 Oct 2026. Prices exclude GST; revenue is always ex-GST.
309	export const PLANS = {
310	  silver: { label: 'Silver', price: 1999 },
311	  gold: { label: 'Gold', price: 4999 },
312	  platinum: { label: 'Platinum', price: 9999 },
313	} as const;
314	export type PlanCode = keyof typeof PLANS;
315	
316	export const PLAN_START_DATE = '2026-10-01';
317	// Every sale before plans were introduced was the ₹799 subscription.
318	export const LEGACY_SALE_PRICE = 799;
319	
320	export function isPlanCode(v: unknown): v is PlanCode {
321	  return typeof v === 'string' && Object.prototype.hasOwnProperty.call(PLANS, v);
322	}
323	
324	export function plansRequiredOn(date: string) {
325	  return date >= PLAN_START_DATE;
326	}
327	
328	// Revenue of one sale dated `date`. Before 1 Oct every sale is ₹799; from 1 Oct it is the
329	// plan price stored on the sale (0 if none was recorded).
330	export function saleRevenue(date: string, planAmount: number | null | undefined) {
331	  if (!plansRequiredOn(date)) return LEGACY_SALE_PRICE;
332	  return Number(planAmount || 0);
333	}
