339	// Last 10 digits of a phone number, or null when there are fewer than 10 digits.
340	export function phoneKey(v: unknown) {
341	  const digits = String(v ?? '').replace(/\D/g, '');
342	  return digits.length >= 10 ? digits.slice(-10) : null;
343	}
