345	// Plan upgrades. A merchant's plan before plans existed is the legacy ₹799 subscription (₹499 is
346	// only its renewal price, so upgrades are always valued from ₹799).
347	export type CurrentPlan = 'legacy' | PlanCode;
348	export const PLAN_RANK: Record<CurrentPlan, number> = { legacy: 0, silver: 1, gold: 2, platinum: 3 };
349	export function planPrice(p: CurrentPlan) {
350	  return p === 'legacy' ? LEGACY_SALE_PRICE : PLANS[p].price;
351	}
352	export function planLabel(p: CurrentPlan) {
353	  return p === 'legacy' ? `₹${LEGACY_SALE_PRICE} plan` : PLANS[p].label;
354	}
355	// Plans a merchant on `from` can upgrade to (only higher plans).
356	export function upgradeTargets(from: CurrentPlan): PlanCode[] {
357	  return (Object.keys(PLANS) as PlanCode[]).filter(p => PLAN_RANK[p] > PLAN_RANK[from]);
358	}
359	// Upgrade value credited for incentives: new plan price minus current plan price.
360	export function upgradeValue(from: CurrentPlan, to: PlanCode) {
361	  return Math.max(0, PLANS[to].price - planPrice(from));
362	}
363	// Sub Raw plan name → plan ("₹799 Plan" / "₹499 Plan" → legacy).
364	export function planFromName(name: unknown): CurrentPlan | null {
365	  const n = String(name ?? '').toLowerCase();
366	  if (!n) return null;
367	  for (const p of Object.keys(PLANS) as PlanCode[]) if (n.includes(PLANS[p].label.toLowerCase())) return p;
368	  if (/799|499/.test(n)) return 'legacy';
369	  return null;
370	}
371	export function isCurrentPlan(v: unknown): v is CurrentPlan {
372	  return v === 'legacy' || isPlanCode(v);
373	}
374	// CSM workspace: merchants whose ads have gone live, worked by Customer Success Managers.
375	//
376	// Built from the latest completed SMB Daily Tracker sync (Sub Raw + AdsRun Raw). A merchant is
377	// in the CSM queues when their ads have run (rows in AdsRun Raw, or completed_ads_count > 0 in
378	// Sub Raw). Every merchant lands in exactly one queue, checked in this order:
379	//   onb_lost  — onboarding closed the case as Not Interested / Refund (shown for context, any ads)
380	//   cancelled — subscription still ACTIVE but the merchant has cancelled (cancelled_at set)
381	//   lapsed    — subscription CANCELLED or EXPIRED
382	//   ending    — subscription active, an ad running now
383	//   ended     — subscription active, no ad running
384	// A merchant whose latest CSM call is Not Interested / Refund moves to "closed" until a CSM
385	// logs something else.
386	// Merchants whose onboarding case the Sub Raw sync reopened (no ad ran, or the ad failed) stay
387	// with onboarding and are left out until the first ad is properly live.
388	
389	export const CSM_L0_CODES = ['OB_IN_PROCESS','OB_NOT_CONNECTED','OB_ADDITIONAL_TOPUP','OB_PLAN_UPGRADED','OB_ANOTHER_AD_LIVE','OB_CREATIVE_UPDATED','OB_SUBS_RENEWED','OB_NOT_INTERESTED','OB_REFUND_REQUESTED'];
390	export const CSM_CLOSING_CODES = ['OB_NOT_INTERESTED','OB_REFUND_REQUESTED'];
391	export type CsmQueue = 'ending'|'ended'|'cancelled'|'lapsed'|'onb_lost';
392	export const CSM_BUCKETS = ['ending','ended','cancelled','lapsed','closed','onb_lost'];
