394	export async function latestCompleteRun(sql:any):Promise<{id:number;finished_at:string;subs_rows:number;ads_rows:number}|null>{
395	  const ok=await sql`SELECT to_regclass('public.csm_sync_runs') IS NOT NULL AS ok`;
396	  if(!ok[0]?.ok) return null;
397	  const rows=await sql`SELECT id,finished_at,subs_rows,ads_rows FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 1`;
398	  return rows[0]||null;
399	}
