401	// Every merchant in the CSM workspace with everything the queue and detail views need.
402	export async function csmMerchants(sql:any,runId:number){
403	  return sql`
404	    WITH subs AS (
405	      SELECT * FROM merchant_subscriptions WHERE sync_run_id=${runId}
406	    ), ads AS (
407	      SELECT customer_id,count(*)::int AS total_ads,
408	        count(*) FILTER (WHERE ad_status='ACTIVE')::int AS active_ads,
409	        count(*) FILTER (WHERE ad_status='COMPLETED')::int AS completed_ads,
410	        max(merchant_name) AS ad_merchant_name,max(phone_number) AS ad_phone
411	      FROM merchant_ads WHERE sync_run_id=${runId} GROUP BY customer_id
412	    ), cases AS (
413	      SELECT DISTINCT ON (customer_id) id,customer_id,current_status,assigned_to,ads_live_at,closed_at,current_l0,current_l1,current_l2,reopen_reason
414	      FROM onboarding_cases ORDER BY customer_id,created_at
415	    ), base AS (
416	      SELECT s.customer_id,s.status AS sub_status,
417	        COALESCE(NULLIF(s.merchant_name,''),a.ad_merchant_name) AS merchant_name,
418	        COALESCE(NULLIF(s.phone_number,''),a.ad_phone) AS phone_number,
419	        s.category,s.sub_category,s.mcc,s.sub_first_date,
420	        s.cancelled_at::text AS cancelled_at,s.expected_renewal_due_date::text AS renewal_due,s.renewal_date::text AS renewal_date,
421	        s.completed_ads_count,s.wallet_balance::float8 AS credits,
422	        COALESCE(a.total_ads,0) AS total_ads,COALESCE(a.active_ads,0) AS active_ads,COALESCE(a.completed_ads,0) AS completed_ads,
423	        c.id AS case_id,c.current_status AS case_status,owner.name AS onboarding_owner,
424	        CASE WHEN c.current_status='lost' THEN concat_ws(' → ',c.current_l0,c.current_l1,c.current_l2) END AS lost_reason,
425	        CASE WHEN c.current_status='lost' THEN c.closed_at END AS lost_at,
426	        CASE WHEN c.current_status='lost' THEN 'onb_lost'
427	             WHEN upper(COALESCE(NULLIF(s.check_sub_status,''),s.status))='ACTIVE' AND s.cancelled_at IS NOT NULL THEN 'cancelled'
428	             WHEN s.status IN ('CANCELLED','EXPIRED') THEN 'lapsed'
429	             WHEN COALESCE(a.active_ads,0)>0 THEN 'ending'
430	             ELSE 'ended' END AS queue
431	      FROM subs s
432	      LEFT JOIN ads a ON a.customer_id=s.customer_id
433	      LEFT JOIN cases c ON c.customer_id=s.customer_id
434	      LEFT JOIN agents owner ON owner.id=c.assigned_to
435	      WHERE (c.current_status='lost' OR COALESCE(a.total_ads,0)>0 OR COALESCE(s.completed_ads_count,0)>0)
436	        -- Reopened by the onboarding sync (no ad ran / ad failed): onboarding owns them until the first ad is live.
437	        AND NOT (c.current_status='open' AND c.reopen_reason IS NOT NULL)
438	    ), cs AS (
439	      SELECT e.customer_id,e.event_time,e.l0_code,e.l0_label_snapshot,e.l1_label_snapshot,e.l2_label_snapshot,e.remark,e.callback_at,e.agent_name_raw,
440	        row_number() OVER (PARTITION BY e.customer_id ORDER BY e.event_time DESC,e.attempt_number DESC) AS rn
441	      FROM onboarding_events e
442	      WHERE e.source_type='customer_success_followup' AND e.customer_id IN (SELECT customer_id FROM base)
443	    ), cs_agg AS (
444	      SELECT customer_id,max(event_time) AS last_outreach,
445	        max(event_time) FILTER (WHERE l0_code<>'OB_NOT_CONNECTED') AS last_connect,
446	        count(*)::int AS cs_calls
447	      FROM cs GROUP BY customer_id
448	    ), money AS (
449	      SELECT e.customer_id,
450	        count(*) FILTER (WHERE (e.l0_code='OB_ADDITIONAL_TOPUP' AND e.top_up_amount_inr>0) OR (e.l0_code='OB_PLAN_UPGRADED' AND e.upgrade_value_inr>0))::int AS topups,
451	        COALESCE(sum(COALESCE(e.top_up_amount_inr,e.upgrade_value_inr)) FILTER (WHERE e.l0_code IN ('OB_ADDITIONAL_TOPUP','OB_PLAN_UPGRADED')),0)::float8 AS topup_total,
452	        count(*) FILTER (WHERE e.l0_code='OB_SUBS_RENEWED')::int AS renewals,
453	        (array_agg(e.plan_code ORDER BY e.event_time DESC) FILTER (WHERE e.l0_code='OB_SUBS_RENEWED'))[1] AS last_renewal_plan
454	      FROM onboarding_events e WHERE e.customer_id IN (SELECT customer_id FROM base)
455	      GROUP BY e.customer_id
456	    ), pitch AS (
457	      SELECT DISTINCT ON (customer_id) customer_id,note,note_date::text AS note_date,author_name
458	      FROM csm_notes WHERE kind='pitch' ORDER BY customer_id,note_date DESC,id DESC
459	    ), sheet_remark AS (
460	      SELECT DISTINCT ON (customer_id) customer_id,note,note_date::text AS note_date,author_name
461	      FROM csm_notes WHERE kind='sheet_remark' ORDER BY customer_id,note_date DESC,id DESC
462	    )
463	    SELECT b.*,
464	      sel.creative_name,sel.description,sel.ad_status,sel.budget::float8 AS budget,sel.start_date::text AS start_date,sel.end_date::text AS end_date,
465	      sel.impressions::float8 AS impressions,sel.clicks::float8 AS clicks,sel.ctr::float8 AS ctr,sel.reach::float8 AS reach,sel.spend::float8 AS spend,
466	      asg.agent_id AS assigned_to,ag.name AS assigned_name,
467	      p.note AS pitch,p.note_date AS pitch_date,p.author_name AS pitch_by,
468	      sr.note AS sheet_remark,sr.note_date AS sheet_remark_date,
469	      ca.last_outreach,ca.last_connect,COALESCE(ca.cs_calls,0) AS cs_calls,
470	      lc.l0_code AS last_l0_code,lc.l0_label_snapshot AS last_l0,lc.l1_label_snapshot AS last_l1,lc.l2_label_snapshot AS last_l2,
471	      lc.remark AS last_remark,lc.agent_name_raw AS last_by,lc.callback_at AS next_callback,
472	      (b.queue<>'onb_lost' AND COALESCE(lc.l0_code IN ('OB_NOT_INTERESTED','OB_REFUND_REQUESTED'),FALSE)) AS closed,
473	      COALESCE(m.topups,0) AS topups,COALESCE(m.topup_total,0) AS topup_total,COALESCE(m.renewals,0) AS renewals,m.last_renewal_plan
474	    FROM base b
475	    LEFT JOIN LATERAL (
476	      SELECT * FROM merchant_ads x WHERE x.sync_run_id=${runId} AND x.customer_id=b.customer_id
477	      ORDER BY
478	        CASE WHEN b.queue='ending' AND x.ad_status='ACTIVE' THEN 0 WHEN b.queue<>'ending' AND x.ad_status='COMPLETED' THEN 0 ELSE 1 END,
479	        CASE WHEN b.queue='ending' THEN x.end_date END ASC NULLS LAST,
480	        CASE WHEN b.queue<>'ending' THEN x.end_date END DESC NULLS LAST,
481	        x.clicks DESC NULLS LAST,
482	        x.end_date DESC NULLS LAST,
483	        x.source_row
484	      LIMIT 1
485	    ) sel ON TRUE
486	    LEFT JOIN csm_assignments asg ON asg.customer_id=b.customer_id
487	    LEFT JOIN agents ag ON ag.id=asg.agent_id
488	    LEFT JOIN pitch p ON p.customer_id=b.customer_id
489	    LEFT JOIN sheet_remark sr ON sr.customer_id=b.customer_id
490	    LEFT JOIN cs_agg ca ON ca.customer_id=b.customer_id
491	    LEFT JOIN cs lc ON lc.customer_id=b.customer_id AND lc.rn=1
492	    LEFT JOIN money m ON m.customer_id=b.customer_id
493	  `;
494	}
495	
496	// Default order inside each queue. The CSM screen can re-sort by impressions, spend or credits.
497	//   cancelled — most credits first
498	//   lapsed    — most recently due for renewal first (yesterday, D-2, ...), then most credits
499	//   ending    — most impressions, then most spend
500	//   ended     — most credits, then most impressions
501	//   onb_lost  — most recently lost first
502	export function sortQueue(rows:any[]){
503	  const t=(d:any)=>d?new Date(d).getTime():0;
504	  const n=(v:any)=>Number(v)||0;
505	  const qOrder:any={ending:0,ended:1,cancelled:2,lapsed:3,onb_lost:4};
506	  return [...rows].sort((a,b)=>{
507	    if(a.queue!==b.queue) return qOrder[a.queue]-qOrder[b.queue];
508	    if(a.queue==='cancelled') return (n(b.credits)-n(a.credits))||(n(b.impressions)-n(a.impressions));
509	    if(a.queue==='lapsed') return (t(b.renewal_due)-t(a.renewal_due))||(n(b.credits)-n(a.credits));
510	    if(a.queue==='ending') return (n(b.impressions)-n(a.impressions))||(n(b.spend)-n(a.spend));
511	    if(a.queue==='ended') return (n(b.credits)-n(a.credits))||(n(b.impressions)-n(a.impressions));
512	    return t(b.lost_at)-t(a.lost_at);
513	  });
514	}
515	
516	// Gives every unassigned merchant an owner, round robin by weight: each new merchant goes to
517	// the CSM whose share (assigned / weight) is lowest. Existing assignments never move.
518	export async function allocateUnassigned(sql:any,runId:number){
519	  const weights=await sql`
520	    SELECT w.agent_id,w.weight,a.name FROM csm_weights w JOIN agents a ON a.id=w.agent_id
521	    JOIN workspace_access wa ON wa.agent_id=a.id AND wa.workspace='csm'
522	    WHERE a.active=TRUE AND w.weight>0 ORDER BY a.name
523	  `;
524	  if(!weights.length) return {assigned:0};
525	  const counts=await sql`SELECT agent_id,count(*)::int AS n FROM csm_assignments GROUP BY agent_id`;
526	  const load=new Map<string,number>(); for(const c of counts) load.set(String(c.agent_id),c.n);
527	  // Onboarding-lost merchants are shown to every CSM for context and are not allocated.
528	  const merchants=sortQueue(await csmMerchants(sql,runId)).filter((m:any)=>!m.assigned_to&&m.queue!=='onb_lost');
529	  const picks:{customer_id:string;agent_id:string}[]=[];
530	  for(const m of merchants){
531	    let best:any=null,bestScore=Infinity;
532	    for(const w of weights){
533	      const score=((load.get(String(w.agent_id))||0)+1)/Number(w.weight);
534	      if(score<bestScore){best=w;bestScore=score;}
535	    }
536	    load.set(String(best.agent_id),(load.get(String(best.agent_id))||0)+1);
537	    picks.push({customer_id:String(m.customer_id),agent_id:String(best.agent_id)});
538	  }
539	  if(picks.length){
540	    await sql`
541	      INSERT INTO csm_assignments(customer_id,agent_id,method)
542	      SELECT x.customer_id,x.agent_id::uuid,'auto' FROM jsonb_to_recordset(${sql.json(picks)}::jsonb) AS x(customer_id text,agent_id text)
543	      ON CONFLICT (customer_id) DO NOTHING
544	    `;
545	  }
546	  return {assigned:picks.length};
547	}
548	
549	// 'admin' for CSM Admins and Super Admins, 'agent' for CSM agents, otherwise null.
550	export function csmRole(user:any):'admin'|'agent'|null{
551	  if(!user) return null;
552	  if(user.isSuperAdmin||user.access?.csm==='admin') return 'admin';
553	  if(user.access?.csm) return 'agent';
554	  return null;
555	}
