package main

import (
	"context"
	"fmt"
	"math"
	"net/http"
	"sort"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// ---- Onboarding roster (lib/onboarding.ts; keep the two in step) ----

type rosterEntry struct {
	ID, Name string
	Count    int
	Last     float64 // epoch ms of the last pick, 0 if never
}

// loadOnboardingRoster: new cases are shared equally among the roster, counted on
// rotation_agent_id since the rotation last gained someone.
func loadOnboardingRoster(ctx context.Context, db DB) ([]*rosterEntry, error) {
	rows, err := db.Query(ctx, `
		WITH r AS (
		  SELECT a.id,a.name,(SELECT max(added_at) FROM onboarding_roster) AS since
		  FROM onboarding_roster o JOIN agents a ON a.id=o.agent_id
		  JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding'
		  WHERE a.active=TRUE
		)
		SELECT r.id::text,r.name,
		  (SELECT count(*)::int FROM onboarding_cases c WHERE c.rotation_agent_id=r.id AND c.created_at>=r.since),
		  COALESCE((SELECT extract(epoch FROM max(c.created_at))*1000 FROM onboarding_cases c WHERE c.rotation_agent_id=r.id),0)::float8
		FROM r ORDER BY r.name`)
	if err != nil {
		return nil, err
	}
	return pgx.CollectRows(rows, func(row pgx.CollectableRow) (*rosterEntry, error) {
		e := &rosterEntry{}
		return e, row.Scan(&e.ID, &e.Name, &e.Count, &e.Last)
	})
}

// takeNextOnboarder: fewest picks, then longest since the last pick, then name.
func takeNextOnboarder(roster []*rosterEntry) *rosterEntry {
	s := append([]*rosterEntry(nil), roster...)
	sort.SliceStable(s, func(i, j int) bool {
		a, b := s[i], s[j]
		if a.Count != b.Count {
			return a.Count < b.Count
		}
		if a.Last != b.Last {
			return a.Last < b.Last
		}
		// ponytail: case-insensitive compare stands in for JS localeCompare; same for plain names.
		return strings.ToLower(a.Name) < strings.ToLower(b.Name)
	})
	next := s[0]
	next.Count++
	next.Last = float64(time.Now().UnixMilli())
	return next
}

// pickOnboarderFallback: no roster set up, so the Onboarding Agent with the fewest open cases.
func pickOnboarderFallback(ctx context.Context, db DB) (*rosterEntry, error) {
	e := &rosterEntry{}
	err := db.QueryRow(ctx, `
		SELECT a.id::text,a.name
		FROM agents a
		JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding' AND w.access_level='agent'
		LEFT JOIN onboarding_cases c ON c.assigned_to=a.id
		WHERE a.active=TRUE
		GROUP BY a.id,a.name
		ORDER BY COUNT(c.id) FILTER (WHERE c.current_status='open') ASC, MAX(c.assigned_at) ASC NULLS FIRST, a.name ASC
		LIMIT 1`).Scan(&e.ID, &e.Name)
	if err == pgx.ErrNoRows {
		return nil, nil
	}
	return e, err
}

// ---- Backlog rebalance, once a day at 8:30 AM IST (lib/onboarding-rebalance.ts) ----

const backlogCap = 10

type rbCase struct {
	ID, CustomerID, AssignedTo string
	Touched                    time.Time
}

type rbPerson struct {
	ID, Name string
	Cases    []rbCase
}

func rebalanceOnboardingBacklog(ctx context.Context, db DB) (map[string]any, error) {
	today := todayIST()
	rows, err := db.Query(ctx, `
		WITH m AS (
		  SELECT DISTINCT ON (t.agent_id) t.agent_id,t.member FROM team_changes t
		  WHERE t.team='onboarding' AND t.effective_from<=$1::date ORDER BY t.agent_id,t.effective_from DESC,t.id DESC
		)
		SELECT a.id::text,a.name,EXISTS(SELECT 1 FROM onboarding_roster r WHERE r.agent_id=a.id)
		FROM m JOIN agents a ON a.id=m.agent_id
		JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding'
		WHERE m.member AND a.active=TRUE`, today)
	if err != nil {
		return nil, err
	}
	var backlog []*rbPerson
	liveIDs := map[string]bool{}
	_, err = pgx.ForEachRow(rows, nil, func() error { return nil })
	if err != nil {
		return nil, err
	}
	rows, err = db.Query(ctx, `
		WITH m AS (
		  SELECT DISTINCT ON (t.agent_id) t.agent_id,t.member FROM team_changes t
		  WHERE t.team='onboarding' AND t.effective_from<=$1::date ORDER BY t.agent_id,t.effective_from DESC,t.id DESC
		)
		SELECT a.id::text,a.name,EXISTS(SELECT 1 FROM onboarding_roster r WHERE r.agent_id=a.id)
		FROM m JOIN agents a ON a.id=m.agent_id
		JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='onboarding'
		WHERE m.member AND a.active=TRUE`, today)
	if err != nil {
		return nil, err
	}
	var id, name string
	var live bool
	if _, err = pgx.ForEachRow(rows, []any{&id, &name, &live}, func() error {
		if live {
			liveIDs[id] = true
		} else {
			backlog = append(backlog, &rbPerson{ID: id, Name: name})
		}
		return nil
	}); err != nil {
		return nil, err
	}
	if len(backlog) == 0 {
		return map[string]any{"moved": 0, "note": "No backlog team"}, nil
	}

	rows, err = db.Query(ctx, `
		SELECT c.id::text,c.customer_id,c.assigned_to::text,COALESCE(c.last_activity_at,c.created_at)
		FROM onboarding_cases c
		LEFT JOIN LATERAL (
		  SELECT e.l0_code FROM onboarding_events e
		  WHERE e.onboarding_case_id=c.id AND e.source_type IN ('new_event','historical_import')
		  ORDER BY e.event_time DESC,e.attempt_number DESC LIMIT 1
		) last ON TRUE
		WHERE c.current_status='open' AND c.assigned_to IS NOT NULL
		  AND (c.created_at AT TIME ZONE 'Asia/Kolkata')::date<$1::date
		  AND (last.l0_code IS NULL OR last.l0_code='OB_NOT_CONNECTED')
		  AND (c.next_callback_at IS NULL OR c.next_callback_at<=now())
		  -- Ever tagged Language Barrier: stays with its owner (who may speak the merchant's language).
		  AND c.language_barrier_at IS NULL
		  AND NOT EXISTS(SELECT 1 FROM onboarding_events lb WHERE lb.onboarding_case_id=c.id AND (lb.l1_code='OB_LANGUAGE_BARRIER' OR lb.l2_code='OB_LANGUAGE_BARRIER'))
		ORDER BY 4 ASC`, today)
	if err != nil {
		return nil, err
	}
	byID := map[string]*rbPerson{}
	for _, p := range backlog {
		byID[p.ID] = p
	}
	var pool []rbCase
	var c rbCase
	if _, err = pgx.ForEachRow(rows, []any{&c.ID, &c.CustomerID, &c.AssignedTo, &c.Touched}, func() error {
		if p := byID[c.AssignedTo]; p != nil {
			p.Cases = append(p.Cases, c)
		} else if liveIDs[c.AssignedTo] {
			pool = append(pool, c)
		}
		return nil
	}); err != nil {
		return nil, err
	}

	total := len(pool)
	for _, p := range backlog {
		total += len(p.Cases)
	}
	target := int(math.Min(backlogCap, math.Ceil(float64(total)/float64(len(backlog)))))
	// Excess over the target leaves its owner (most recently touched stays; oldest-touched moves).
	for _, p := range backlog {
		for len(p.Cases) > target {
			pool = append(pool, p.Cases[0])
			p.Cases = p.Cases[1:]
		}
	}
	sort.SliceStable(pool, func(i, j int) bool { return pool[i].Touched.Before(pool[j].Touched) })
	type move struct {
		c  rbCase
		to *rbPerson
	}
	var moves []move
	for _, c := range pool {
		s := append([]*rbPerson(nil), backlog...)
		sort.SliceStable(s, func(i, j int) bool {
			if len(s[i].Cases) != len(s[j].Cases) {
				return len(s[i].Cases) < len(s[j].Cases)
			}
			return strings.ToLower(s[i].Name) < strings.ToLower(s[j].Name)
		})
		to := s[0]
		if len(to.Cases) >= target {
			break
		}
		to.Cases = append(to.Cases, c)
		if c.AssignedTo != to.ID {
			moves = append(moves, move{c, to})
		}
	}
	for _, m := range moves {
		err := pgx.BeginFunc(ctx, pool_(db), func(tx pgx.Tx) error {
			tag, err := tx.Exec(ctx, `UPDATE onboarding_cases SET assigned_to=$1::uuid,assigned_at=now(),updated_at=now()
				WHERE id=$2::uuid AND current_status='open' AND assigned_to=$3::uuid`, m.to.ID, m.c.ID, m.c.AssignedTo)
			if err != nil || tag.RowsAffected() == 0 {
				return err
			}
			_, err = tx.Exec(ctx, `INSERT INTO onboarding_events(onboarding_case_id,customer_id,attempt_number,agent_name_raw,source_type,l0_code,l0_label_snapshot,remark)
				SELECT $1::uuid,$2,COALESCE(MAX(attempt_number),0)+1,'Backlog rebalance','assignment','SYSTEM_REASSIGNED','Reassigned',$3
				FROM onboarding_events WHERE onboarding_case_id=$1::uuid`,
				m.c.ID, m.c.CustomerID, fmt.Sprintf("Reassigned to %s by the 8:30 AM backlog rebalance", m.to.Name))
			return err
		})
		if err != nil {
			return nil, err
		}
	}
	after := map[string]int{}
	for _, p := range backlog {
		after[p.Name] = len(p.Cases)
	}
	return map[string]any{"moved": len(moves), "target": target, "noTalkCases": total, "backlogPeople": len(backlog), "after": after}, nil
}

// runDailyJobs runs the day's once-a-day jobs that are due; daily_jobs makes each run once a day.
func runDailyJobs(ctx context.Context, db DB) error {
	now := time.Now().In(ist)
	if now.Hour()*60+now.Minute() < 8*60+30 {
		return nil
	}
	today := todayIST()
	tag, err := db.Exec(ctx, `INSERT INTO daily_jobs(job,run_date) VALUES('onboarding_backlog_rebalance',$1::date) ON CONFLICT DO NOTHING`, today)
	if err != nil || tag.RowsAffected() == 0 {
		return err
	}
	result, err := rebalanceOnboardingBacklog(ctx, db)
	if err != nil {
		result = map[string]any{"error": err.Error()}
	}
	_, err2 := db.Exec(ctx, `UPDATE daily_jobs SET result=$1::jsonb WHERE job='onboarding_backlog_rebalance' AND run_date=$2::date`, toJSON(result), today)
	if err != nil {
		return err
	}
	return err2
}

// pool_ gives BeginFunc the pool when db is the pool (helpers are called with either).
func pool_(db DB) interface {
	Begin(context.Context) (pgx.Tx, error)
} {
	if t, ok := db.(pgx.Tx); ok {
		return t
	}
	return pool
}

// ---- Sub Raw → onboarding cases (app/api/internal/sub-raw-onboarding-sync) ----

type subRow struct {
	CustomerID, SubFirstDate string
	Ads                      float64
	FirstAdDate              *string
	SourceRow                *int
	// Delivery fields are only trusted when the script sent them (older script versions do not).
	DeliveryKnown       bool
	Impressions, Spend  float64
	LatestAdStatus      string
	SubFieldsKnown      bool
	SubStatus           *string
	CancelledAt         *string
	Credits             *float64
	Stage               *string
	PlanKnown           bool
	ExpiryKnown         bool
	PlanName            *string
	PlanAmount          *float64
	Expiry              *string
	Mid                 *string
}

// plans in lib/plans.ts order (label, price ex-GST).
var plans = []struct {
	Label string
	Price float64
}{{"Silver", 1999}, {"Gold", 4999}, {"Platinum", 9999}}

// sheetNumber: commas dropped; blank → 0; negative or not a number → null.
func sheetNumber(v any) *float64 {
	t := strings.TrimSpace(strings.ReplaceAll(jsString(v), ",", ""))
	zero := 0.0
	if t == "" {
		return &zero
	}
	f, ok := toNumber(t)
	if !ok || math.IsInf(f, 0) || f < 0 {
		return nil
	}
	return &f
}

// planAmountOf: the sheet's amount when sent, otherwise the list price from the plan name.
func planAmountOf(amount, name any) *float64 {
	if t := keepChars(jsString(amount), "0123456789."); t != "" {
		if f, ok := toNumber(t); ok && f > 0 {
			return &f
		}
	}
	n := strings.ToLower(jsString(name))
	for _, p := range plans {
		if strings.Contains(n, strings.ToLower(p.Label)) {
			price := p.Price
			return &price
		}
	}
	return nil
}

func isAlnum6(s string) bool {
	if len(s) < 6 {
		return false
	}
	for _, c := range s {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z') {
			return false
		}
	}
	return true
}

func normalizeSubRow(raw map[string]any) *subRow {
	if raw == nil {
		return nil
	}
	r := &subRow{
		CustomerID:   strings.TrimSpace(jsString(raw["customerId"])),
		SubFirstDate: strings.TrimSpace(jsString(raw["subFirstDate"])),
	}
	firstAd := strings.TrimSpace(jsString(raw["firstAdDate"]))
	ads, adsOK := jsNumber(raw, "totalAdsExecuted")
	if !allDigits(r.CustomerID) || !isISODate(r.SubFirstDate) || !adsOK || math.IsInf(ads, 0) || ads < 0 {
		return nil
	}
	if firstAd != "" && !isISODate(firstAd) {
		return nil
	}
	r.Ads = ads
	if firstAd != "" {
		r.FirstAdDate = &firstAd
	}
	if sr, ok := jsNumber(raw, "sourceRow"); isInteger(sr, ok) && sr > 0 {
		n := int(sr)
		r.SourceRow = &n
	}
	var impressions, spend *float64
	if v, ok := raw["totalImpressions"]; ok {
		impressions = sheetNumber(v)
	}
	if v, ok := raw["totalSpend"]; ok {
		spend = sheetNumber(v)
	}
	r.DeliveryKnown = impressions != nil && spend != nil
	if impressions != nil {
		r.Impressions = *impressions
	}
	if spend != nil {
		r.Spend = *spend
	}
	r.LatestAdStatus = strings.ToUpper(strings.TrimSpace(jsString(raw["latestAdStatus"])))
	_, r.SubFieldsKnown = raw["subscriptionStatus"]
	if s := strings.ToUpper(strings.TrimSpace(jsString(raw["subscriptionStatus"]))); s != "" {
		r.SubStatus = &s
	}
	r.CancelledAt = isoOrNil(raw["cancelledAt"])
	if v, ok := raw["credits"]; ok && v != nil && v != "" {
		r.Credits = sheetNumber(keepChars(jsString(v), "0123456789.-"))
	}
	r.Stage = txt(raw["lastCompletedStage"])
	_, r.PlanKnown = raw["planName"]
	_, r.ExpiryKnown = raw["expiryDate"]
	r.PlanName = txt(raw["planName"])
	r.PlanAmount = planAmountOf(raw["planAmount"], raw["planName"])
	r.Expiry = isoOrNil(raw["expiryDate"])
	if m := strings.TrimSpace(jsString(raw["mid"])); isAlnum6(m) {
		r.Mid = &m
	}
	return r
}

type subCase struct {
	ID, Status  string
	AdsLiveSet  bool
	AdsLiveDay  *string
	HasExternal bool
}

// checkOnboarderLive: an onboarder-marked Ads Live case at least a day old is checked against Sub Raw.
//
//	REOPEN        – no ad has ever run (0 ads executed, 0 impressions, 0 spend)
//	REOPEN_FAILED – the ad ran (impressions or spend) but its latest status is FAILED
//	OK            – anything else, including PAUSED and rows without delivery fields
func checkOnboarderLive(c *subCase, row *subRow, cutoff string) string {
	if c.Status != "ads_live" || c.HasExternal {
		return "OK"
	}
	if c.AdsLiveDay == nil || *c.AdsLiveDay > cutoff {
		return "OK"
	}
	if !row.DeliveryKnown || row.Ads > 0 {
		return "OK"
	}
	if row.Impressions == 0 && row.Spend == 0 {
		return "REOPEN"
	}
	if row.LatestAdStatus == "FAILED" {
		return "REOPEN_FAILED"
	}
	return "OK"
}

const caseQuery = `
	SELECT c.id::text,COALESCE(c.current_status,''),c.ads_live_at IS NOT NULL,
	  (c.ads_live_at AT TIME ZONE 'Asia/Kolkata')::date::text,
	  EXISTS (SELECT 1 FROM onboarding_events e WHERE e.onboarding_case_id=c.id AND e.l0_code='SYSTEM_EXTERNAL_ADS_LIVE')
	FROM onboarding_cases c
	WHERE c.customer_id=$1
	ORDER BY c.created_at ASC
	LIMIT 1`

func loadSubCase(ctx context.Context, db DB, customerID string, forUpdate bool) (*subCase, error) {
	q := caseQuery
	if forUpdate {
		q += " FOR UPDATE OF c"
	}
	c := &subCase{}
	err := db.QueryRow(ctx, q, customerID).Scan(&c.ID, &c.Status, &c.AdsLiveSet, &c.AdsLiveDay, &c.HasExternal)
	if err == pgx.ErrNoRows {
		return nil, nil
	}
	return c, err
}

func subRawSync(w http.ResponseWriter, r *http.Request) error {
	if !subRawSecretOK(r) {
		return fail(401, "Unauthorized")
	}
	body := obj(readJSON(r))
	cutoff := strings.TrimSpace(jsString(body["cutoffDate"]))
	dryRun := truthy(body["dryRun"])
	if !isISODate(cutoff) {
		return fail(400, "cutoffDate must be YYYY-MM-DD")
	}
	maxCutoff := time.Now().In(ist).AddDate(0, 0, -1).Format("2006-01-02")
	if cutoff > maxCutoff {
		return fail(400, fmt.Sprintf("cutoffDate cannot be later than T-1 (%s)", maxCutoff))
	}
	input := arr(body["rows"])
	if len(input) > 100 {
		return fail(400, "Send at most 100 rows per request.")
	}

	invalidRows := []float64{}
	var order []string // Map insertion order: a repeated Cust ID keeps its first position, latest row.
	deduped := map[string]*subRow{}
	for i, raw := range input {
		row := normalizeSubRow(obj(raw))
		if row == nil {
			n, ok := jsNumber(obj(raw), "sourceRow")
			if !ok || n == 0 {
				n = float64(i + 1)
			}
			invalidRows = append(invalidRows, n)
			continue
		}
		// Sub Raw is authoritative. Ignore subscriptions newer than the requested T-1 cutoff.
		if row.SubFirstDate > cutoff {
			continue
		}
		if deduped[row.CustomerID] == nil {
			order = append(order, row.CustomerID)
		}
		deduped[row.CustomerID] = row
	}

	ctx := r.Context()
	roster, err := loadOnboardingRoster(ctx, pool)
	if err != nil {
		return err
	}
	if len(roster) == 0 {
		return fail(409, "No active onboarders in the onboarding roster.")
	}

	s := map[string]any{
		"inputRows": len(input), "eligibleRows": len(deduped), "invalidRows": invalidRows,
		"createdOpen": 0, "createdOpenDhruv": 0, "createdOpenAshish": 0, "createdOpenPriyanshi": 0,
		"createdExternalLive": 0, "existingMarkedExternalLive": 0, "alreadyAdsLive": 0, "adsLiveReopened": 0,
		"adFailedAfterLiveReopened": 0, "existingOpenNoChange": 0, "lostNoChange": 0, "lostMarkedExternalLive": 0,
		"otherNoChange": 0, "missingFirstAdDate": 0,
	}
	actions := []map[string]string{}
	inc := func(k string) { n, _ := s[k].(int); s[k] = n + 1 }
	act := func(id, a string) { actions = append(actions, map[string]string{"customerId": id, "action": a}) }
	countCreated := func(name string) { inc("createdOpen"); inc("createdOpen" + name) }

	for _, id := range order {
		row := deduped[id]
		liveAsOfCutoff := row.Ads > 0 && row.FirstAdDate != nil && *row.FirstAdDate <= cutoff
		if row.Ads > 0 && row.FirstAdDate == nil {
			inc("missingFirstAdDate")
			act(id, "SKIP_MISSING_FIRST_AD_DATE")
			continue
		}

		if dryRun {
			c, err := loadSubCase(ctx, pool, id, false)
			if err != nil {
				return err
			}
			switch {
			case c == nil && liveAsOfCutoff:
				inc("createdExternalLive")
				act(id, "CREATE_EXTERNAL_ADS_LIVE")
			case c == nil:
				t := takeNextOnboarder(roster)
				countCreated(t.Name)
				act(id, "CREATE_OPEN_"+strings.ToUpper(t.Name))
			case c.Status == "ads_live" || c.AdsLiveSet:
				switch checkOnboarderLive(c, row, cutoff) {
				case "REOPEN":
					inc("adsLiveReopened")
					act(id, "REOPEN_ADS_LIVE_NOT_VERIFIED")
				case "REOPEN_FAILED":
					inc("adFailedAfterLiveReopened")
					act(id, "REOPEN_AD_FAILED_AFTER_LIVE")
				default:
					inc("alreadyAdsLive")
				}
			case c.Status == "lost" && liveAsOfCutoff:
				inc("lostMarkedExternalLive")
				act(id, "MARK_LOST_EXTERNAL_ADS_LIVE")
			case c.Status == "lost":
				inc("lostNoChange")
			case c.Status == "open" && liveAsOfCutoff:
				inc("existingMarkedExternalLive")
				act(id, "MARK_EXTERNAL_ADS_LIVE")
			case c.Status == "open":
				inc("existingOpenNoChange")
			default:
				inc("otherNoChange")
			}
			continue
		}

		err := pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
			if _, err := tx.Exec(ctx, `SELECT pg_advisory_xact_lock(hashtext($1))`, id); err != nil {
				return err
			}
			c, err := loadSubCase(ctx, tx, id, true)
			if err != nil {
				return err
			}
			nextAttempt := func() (int, error) {
				var n int
				err := tx.QueryRow(ctx, `SELECT COALESCE(MAX(attempt_number),0)+1 FROM onboarding_events WHERE onboarding_case_id=$1::uuid`, c.ID).Scan(&n)
				return n, err
			}
			event := func(caseID string, attempt int, sourceType, code, label, remark string) error {
				_, err := tx.Exec(ctx, `
					INSERT INTO onboarding_events(onboarding_case_id,customer_id,attempt_number,source_type,source_sheet,source_row,l0_code,l0_label_snapshot,remark)
					VALUES($1::uuid,$2,$3,$4,'Sub Raw',$5,$6,$7,$8)`, caseID, id, attempt, sourceType, row.SourceRow, code, label, remark)
				return err
			}

			if c == nil {
				if _, err := tx.Exec(ctx, `INSERT INTO customers(customer_id) VALUES($1) ON CONFLICT (customer_id) DO NOTHING`, id); err != nil {
					return err
				}
				var caseID string
				if liveAsOfCutoff {
					if err := tx.QueryRow(ctx, `
						INSERT INTO onboarding_cases(customer_id,source_type,sale_date,current_l0,current_status,last_activity_at,ads_live_at,closed_at)
						VALUES($1,'historical_import',$2::date,'Externally Ads Live','ads_live',now(),
						  ($3::date::timestamp AT TIME ZONE 'Asia/Kolkata'),($3::date::timestamp AT TIME ZONE 'Asia/Kolkata'))
						RETURNING id::text`, id, row.SubFirstDate, *row.FirstAdDate).Scan(&caseID); err != nil {
						return err
					}
					if err := event(caseID, 1, "system", "SYSTEM_EXTERNAL_ADS_LIVE", "Externally Ads Live",
						"Ads execution detected from Sub Raw T-1 sync; closed externally."); err != nil {
						return err
					}
					inc("createdExternalLive")
					act(id, "CREATE_EXTERNAL_ADS_LIVE")
					return nil
				}
				t := takeNextOnboarder(roster)
				if err := tx.QueryRow(ctx, `
					INSERT INTO onboarding_cases(customer_id,source_type,sale_date,assigned_to,assigned_at,last_activity_at,rotation_agent_id)
					VALUES($1,'historical_import',$2::date,$3::uuid,now(),NULL,$3::uuid)
					RETURNING id::text`, id, row.SubFirstDate, t.ID).Scan(&caseID); err != nil {
					return err
				}
				if err := event(caseID, 1, "assignment", "SYSTEM_ASSIGNED", "Assigned",
					fmt.Sprintf("Assigned to %s by Sub Raw T-1 sync", t.Name)); err != nil {
					return err
				}
				countCreated(t.Name)
				act(id, "CREATE_OPEN_"+strings.ToUpper(t.Name))
				return nil
			}

			if c.Status == "ads_live" || c.AdsLiveSet {
				check := checkOnboarderLive(c, row, cutoff)
				if check == "OK" {
					inc("alreadyAdsLive")
					return nil
				}
				n, err := nextAttempt()
				if err != nil {
					return err
				}
				// Marked Ads Live by an onboarder, but Sub Raw shows no ad has run, or the ad ran and
				// then failed. Keep the onboarder's entry in the history and put the case back in the
				// open queue; clearing ads_live_at takes it out of the Ads Live counts and incentives.
				failed := check == "REOPEN_FAILED"
				day := ""
				if c.AdsLiveDay != nil {
					day = *c.AdsLiveDay
				}
				code, label, reason := "SYSTEM_ADS_LIVE_NOT_VERIFIED", "Ads Live Not Verified", "no_ad_ran"
				remark := fmt.Sprintf("Marked Ads Live on %s, but Sub Raw shows no ad has run (0 ads executed, 0 impressions, 0 spend) as of %s. Case reopened by the T-1 sync.", day, cutoff)
				if failed {
					code, label, reason = "SYSTEM_AD_FAILED_AFTER_LIVE", "Ad Failed After Live", "ad_failed"
					remark = fmt.Sprintf("Marked Ads Live on %s; the ad ran (%s impressions, Rs %s spent) but its latest status is FAILED as of %s. Case reopened by the T-1 sync.",
						day, fmtNum(row.Impressions), fmtNum(row.Spend), cutoff)
				}
				if err := event(c.ID, n, "system", code, label, remark); err != nil {
					return err
				}
				if _, err := tx.Exec(ctx, `
					UPDATE onboarding_cases
					SET current_l0=$1,current_l1=NULL,current_l2=NULL,current_status='open',
					    ads_live_at=NULL,closed_at=NULL,next_callback_at=now(),last_activity_at=now(),updated_at=now(),
					    reopened_at=now(),reopen_reason=$2
					WHERE id=$3::uuid`, label, reason, c.ID); err != nil {
					return err
				}
				if failed {
					inc("adFailedAfterLiveReopened")
					act(id, "REOPEN_AD_FAILED_AFTER_LIVE")
				} else {
					inc("adsLiveReopened")
					act(id, "REOPEN_ADS_LIVE_NOT_VERIFIED")
				}
				return nil
			}
			if c.Status == "lost" && liveAsOfCutoff {
				// The merchant went live on their own after the case was closed as lost. Keep the
				// lost status; only record the external Ads Live for the counts and the rate.
				n, err := nextAttempt()
				if err != nil {
					return err
				}
				if err := event(c.ID, n, "system", "SYSTEM_EXTERNAL_ADS_LIVE", "Externally Ads Live",
					"Ads execution detected from Sub Raw T-1 sync after the case was closed as lost; lost disposition retained."); err != nil {
					return err
				}
				if _, err := tx.Exec(ctx, `UPDATE onboarding_cases SET ads_live_at=($1::date::timestamp AT TIME ZONE 'Asia/Kolkata'),updated_at=now() WHERE id=$2::uuid`,
					*row.FirstAdDate, c.ID); err != nil {
					return err
				}
				inc("lostMarkedExternalLive")
				act(id, "MARK_LOST_EXTERNAL_ADS_LIVE")
				return nil
			}
			if c.Status == "lost" {
				inc("lostNoChange")
				return nil
			}
			if c.Status == "open" && !liveAsOfCutoff {
				inc("existingOpenNoChange")
				return nil
			}
			if c.Status != "open" {
				inc("otherNoChange")
				return nil
			}
			n, err := nextAttempt()
			if err != nil {
				return err
			}
			if err := event(c.ID, n, "system", "SYSTEM_EXTERNAL_ADS_LIVE", "Externally Ads Live",
				"Ads execution detected from Sub Raw T-1 sync; closed externally."); err != nil {
				return err
			}
			if _, err := tx.Exec(ctx, `
				UPDATE onboarding_cases
				SET current_l0='Externally Ads Live',current_l1=NULL,current_l2=NULL,current_status='ads_live',
				    next_callback_at=NULL,last_activity_at=now(),
				    ads_live_at=($1::date::timestamp AT TIME ZONE 'Asia/Kolkata'),
				    closed_at=($1::date::timestamp AT TIME ZONE 'Asia/Kolkata'),
				    updated_at=now()
				WHERE id=$2::uuid`, *row.FirstAdDate, c.ID); err != nil {
				return err
			}
			inc("existingMarkedExternalLive")
			act(id, "MARK_EXTERNAL_ADS_LIVE")
			return nil
		})
		if err != nil {
			return err
		}
	}

	// Sub Raw fields on every matching case (pills, sorting, stage filter on the onboarding screen).
	var subFields []map[string]any
	for _, id := range order {
		r := deduped[id]
		if r.SubFieldsKnown {
			subFields = append(subFields, map[string]any{"customer_id": id, "status": r.SubStatus, "cancelled_at": r.CancelledAt,
				"credits": r.Credits, "stage": r.Stage, "plan_known": r.PlanKnown, "plan": r.PlanName, "amount": r.PlanAmount,
				"expiry_known": r.ExpiryKnown, "expiry": r.Expiry})
		}
	}
	if !dryRun && len(subFields) > 0 {
		if _, err := pool.Exec(ctx, `
			UPDATE onboarding_cases c SET sub_status=x.status,sub_cancelled_at=x.cancelled_at::date,sub_credits=x.credits,
			  last_completed_stage=x.stage,sub_plan_name=CASE WHEN x.plan_known THEN x.plan ELSE c.sub_plan_name END,
			  sub_plan_amount=CASE WHEN x.plan_known THEN x.amount ELSE c.sub_plan_amount END,
			  sub_expiry_date=CASE WHEN x.expiry_known THEN x.expiry::date ELSE c.sub_expiry_date END,sub_synced_at=now()
			FROM jsonb_to_recordset($1::jsonb) AS x(customer_id text,status text,cancelled_at text,credits numeric,stage text,plan_known boolean,plan text,amount numeric,expiry_known boolean,expiry text)
			WHERE c.customer_id=x.customer_id`, toJSON(subFields)); err != nil {
			return err
		}
	}
	if dryRun {
		s["subFieldsUpdated"] = 0
	} else {
		s["subFieldsUpdated"] = len(subFields)
		// CleverTap payments that came with only a MID: link them now that Sub Raw gives the Cust ID.
		known := []map[string]string{}
		for _, id := range order {
			if m := deduped[id].Mid; m != nil {
				known = append(known, map[string]string{"mid": *m, "customer_id": id})
			}
		}
		linked, codes, err := linkCtPayments(ctx, pool, known)
		if err != nil {
			return err
		}
		s["ctPaymentsLinked"], s["ctEmployeeCodesAdded"] = linked, codes
	}
	s["ok"], s["dryRun"], s["cutoffDate"], s["actions"] = true, dryRun, cutoff, actions
	return writeJSON(w, 200, s)
}

