	_, err2 := pool.Exec(ctx, `UPDATE daily_jobs SET result=$1::jsonb WHERE job='onboarding_backlog_rebalance' AND run_date=$2::date`, toJSON(result), today)
	if err != nil {
		return err
	}
	return err2
}

