// Go API server for the machine-only endpoints: the Apps Script syncs and the CleverTap webhook.
// Same paths, secrets, request bodies and responses as the Next.js routes they replace, so the
// cutover is only the host in each script's URL property. Everything with a UI or a login session
// stays in Next.js; WhatsApp sending also stays there (lib/wa.ts) and is triggered through
// /api/internal/wa-run, so the template config lives in one place.
package main

import (
	"context"
	"crypto/subtle"
	"encoding/json"
	"errors"
	"log"
	"math"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// DB is what both the pool and a transaction offer, so helpers run either way.
type DB interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

var pool *pgxpool.Pool

func main() {
	if os.Getenv("DATABASE_URL") == "" {
		log.Fatal("DATABASE_URL is not set")
	}
	cfg, err := pgxpool.ParseConfig(os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	cfg.MaxConns = 5
	cfg.MaxConnLifetime = 5 * time.Minute
	cfg.MaxConnIdleTime = 20 * time.Second
	// No server-side prepared statements, as in lib/db.ts: Neon's pooler doesn't keep them across
	// transactions, and a cached plan breaks when a migration adds columns.
	cfg.ConnConfig.DefaultQueryExecMode = pgx.QueryExecModeSimpleProtocol
	pool, err = pgxpool.NewWithConfig(context.Background(), cfg)
	if err != nil {
		log.Fatal(err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) })
	mux.HandleFunc("POST /api/internal/sub-raw-onboarding-sync", handle(subRawSync))
	mux.HandleFunc("POST /api/internal/csm-sync", handle(csmSync))
	mux.HandleFunc("POST /api/admin/merchant-sync", handle(merchantSync))
	mux.HandleFunc("POST /api/internal/leadgen-sync", handle(leadgenSync))
	mux.HandleFunc("POST /api/internal/ad-conversions-sync", handle(adConversionsSync))
	mux.HandleFunc("POST /api/internal/ct-payment", handle(ctPayment))

	// Once-a-day jobs on their own clock (in Next.js they rode on the 5-minute lead sync). The
	// daily_jobs claim keeps them to one run a day even while the Next.js route still runs them.
	go func() {
		for range time.Tick(5 * time.Minute) {
			if err := runDailyJobs(context.Background(), pool); err != nil {
				log.Printf("daily jobs failed: %v", err)
			}
		}
	}()

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}

// ---- HTTP ----

type httpError struct {
	status int
	body   map[string]any
}

func (e *httpError) Error() string { return jsString(e.body["error"]) }

func fail(status int, msg string) error {
	return &httpError{status, map[string]any{"error": msg}}
}

func handle(h func(w http.ResponseWriter, r *http.Request) error) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		err := h(w, r)
		if err == nil {
			return
		}
		var he *httpError
		if errors.As(err, &he) {
			writeJSON(w, he.status, he.body)
			return
		}
		log.Printf("%s %s: %v", r.Method, r.URL.Path, err)
		writeJSON(w, 500, map[string]any{"error": err.Error()})
	}
}

func writeJSON(w http.ResponseWriter, status int, v any) error {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	return json.NewEncoder(w).Encode(v)
}

// readJSON mirrors `await req.json().catch(()=>null)`: a body that isn't JSON comes back nil.
func readJSON(r *http.Request) any {
	var v any
	if json.NewDecoder(r.Body).Decode(&v) != nil {
		return nil
	}
	return v
}

func sameSecret(configured, supplied string) bool {
	return configured != "" && supplied != "" && subtle.ConstantTimeCompare([]byte(configured), []byte(supplied)) == 1
}

// subRawSecretOK is the check shared by the Sub Raw, CSM, lead gen and ad conversion syncs.
func subRawSecretOK(r *http.Request) bool {
	return sameSecret(os.Getenv("SUB_RAW_SYNC_SECRET"), r.Header.Get("x-sub-raw-sync-secret"))
}

// triggerNext runs a WhatsApp job in Next.js (app/api/internal/wa-run), after the response.
func triggerNext(job string) {
	go func() {
		base := strings.TrimRight(os.Getenv("NEXT_BASE_URL"), "/")
		if base == "" {
			log.Printf("wa-run %s skipped: NEXT_BASE_URL is not set", job)
			return
		}
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Minute)
		defer cancel()
		body, _ := json.Marshal(map[string]string{"job": job})
		req, _ := http.NewRequestWithContext(ctx, "POST", base+"/api/internal/wa-run", strings.NewReader(string(body)))
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("x-sub-raw-sync-secret", os.Getenv("SUB_RAW_SYNC_SECRET"))
		res, err := http.DefaultClient.Do(req)
		if err != nil {
			log.Printf("wa-run %s failed: %v", job, err)
			return
		}
		res.Body.Close()
		if res.StatusCode != 200 {
			log.Printf("wa-run %s: HTTP %d", job, res.StatusCode)
		}
	}()
}

// ---- JS value semantics (the scripts send loosely typed JSON) ----

var ist = time.FixedZone("IST", 330*60)

func todayIST() string        { return time.Now().In(ist).Format("2006-01-02") }
func istDay(t time.Time) string { return t.In(ist).Format("2006-01-02") }

func obj(v any) map[string]any { m, _ := v.(map[string]any); return m }
func arr(v any) []any          { a, _ := v.([]any); return a }

// jsString is String(v ?? '').
func jsString(v any) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return x
	case float64:
		return fmtNum(x)
	case bool:
		return strconv.FormatBool(x)
	default:
		b, _ := json.Marshal(x)
		return string(b)
	}
}

// fmtNum prints a number the way JS does in a template string (1999, 1999.5).
func fmtNum(f float64) string { return strconv.FormatFloat(f, 'f', -1, 64) }

// jsNumber is Number(v); ok is false for NaN. A missing key is undefined (NaN), JSON null is 0.
func jsNumber(m map[string]any, key string) (float64, bool) {
	v, present := m[key]
	if !present {
		return 0, false
	}
	return toNumber(v)
}

func toNumber(v any) (float64, bool) {
	switch x := v.(type) {
	case nil:
		return 0, true
	case float64:
		return x, true
	case bool:
		if x {
			return 1, true
		}
		return 0, true
	case string:
		t := strings.TrimSpace(x)
		if t == "" {
			return 0, true
		}
		f, err := strconv.ParseFloat(t, 64)
		return f, err == nil
	}
	return 0, false
}

func isInteger(f float64, ok bool) bool { return ok && !math.IsInf(f, 0) && f == math.Trunc(f) }

// orZero is `Number(v)||0`.
func orZero(f float64, ok bool) float64 {
	if !ok {
		return 0
	}
	return f
}

func truthy(v any) bool {
	switch x := v.(type) {
	case nil:
		return false
	case bool:
		return x
	case float64:
		return x != 0 && !math.IsNaN(x)
	case string:
		return x != ""
	}
	return true
}

func isISODate(s string) bool {
	if len(s) != 10 || s[4] != '-' || s[7] != '-' {
		return false
	}
	for i, c := range s {
		if i != 4 && i != 7 && (c < '0' || c > '9') {
			return false
		}
	}
	return true
}

func allDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

// keepChars drops every character not in `allowed` (the scripts' /[^0-9.\-]/g replaces).
func keepChars(s, allowed string) string {
	return strings.Map(func(r rune) rune {
		if strings.ContainsRune(allowed, r) {
			return r
		}
		return -1
	}, s)
}

// sheetNum is the syncs' `num`: digits, dot and minus kept; blank or unparseable → null.
func sheetNum(v any) *float64 {
	t := strings.TrimSpace(keepChars(jsString(v), "0123456789.-"))
	if t == "" {
		return nil
	}
	f, err := strconv.ParseFloat(t, 64)
	if err != nil || math.IsInf(f, 0) {
		return nil
	}
	return &f
}

// txt is `String(v??'').trim()||null`.
func txt(v any) *string {
	t := strings.TrimSpace(jsString(v))
	if t == "" {
		return nil
	}
	return &t
}

// sheetID is a Cust ID / ad ID cell: digits only, a trailing ".0" from a number cell dropped.
func sheetID(v any) *string {
	t := strings.TrimSuffix(strings.TrimSpace(jsString(v)), ".0")
	if !allDigits(t) {
		return nil
	}
	return &t
}

func isoOrNil(v any) *string {
	t := strings.TrimSpace(jsString(v))
	if !isISODate(t) {
		return nil
	}
	return &t
}

func toJSON(v any) string { b, _ := json.Marshal(v); return string(b) }

// truncRunes cuts to n characters without splitting one (Postgres refuses broken UTF-8).
func truncRunes(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

