	}
	if s == "1" || s == "" {
		return nil
	}
	return &s
}

func ctPick(srcs []map[string]any, names ...string) any {
	for _, src := range srcs {
		if src == nil {
			continue
		}
		for _, n := range names {
			if v, ok := src[n]; ok && v != nil && strings.TrimSpace(jsString(v)) != "" {
				return v
			}
		}
	}
	return nil
