	if v == nil || v == "" {
		return nil
	}
	if n, ok := toNumber(v); ok && !math.IsInf(n, 0) {
		if n < 1e12 {
			n *= 1000
		}
		t := time.UnixMilli(int64(n))
		return &t
	}
