	e.Plan = lower(ctVal(ctPick(srcs, "plan", "event_label2")))
	e.EmployeeCode = ctVal(ctPick(srcs, "employee_code", "employeeCode", "event_label4"))
	e.Category = lower(ctVal(ctPick(srcs, "category", "event_category", "payload_event_category")))
	e.Action = lower(ctVal(ctPick(srcs, "action", "event_action", "payload_event_action")))
