package main

import (
	"context"
	"fmt"
	"net/http"
	"sort"
	"strings"

	"github.com/jackc/pgx/v5"
)

// Daily push of the SMB Daily Tracker's Sub Raw and AdsRun Raw tabs (scripts/csm-sync.gs).
// Protocol: start → subs / ads batches → finish. Rows are written under a new run and only become
// visible when finish succeeds, so a failed or partial push never replaces good data.

func csmSync(w http.ResponseWriter, r *http.Request) error {
	if !subRawSecretOK(r) {
		return fail(401, "Unauthorized")
	}
	ctx := r.Context()
	body := obj(readJSON(r))
	action := jsString(body["action"])

	if action == "start" {
		if _, err := pool.Exec(ctx, `UPDATE csm_sync_runs SET status='failed',finished_at=now(),note='abandoned' WHERE status='running' AND started_at<now()-interval '1 hour'`); err != nil {
			return err
		}
		var id int64
		if err := pool.QueryRow(ctx, `INSERT INTO csm_sync_runs(status) VALUES('running') RETURNING id`).Scan(&id); err != nil {
			return err
		}
		return writeJSON(w, 200, map[string]any{"ok": true, "runId": id})
	}

	runF, ok := jsNumber(body, "runId")
	if !isInteger(runF, ok) {
		return fail(400, "runId is required")
	}
	runID := int64(runF)
	var status string
	if err := pool.QueryRow(ctx, `SELECT status FROM csm_sync_runs WHERE id=$1`, runID).Scan(&status); err != nil && err != pgx.ErrNoRows {
		return err
	}
	if status != "running" {
		return fail(409, "This sync run is not open.")
	}
	input := arr(body["rows"])
	if len(input) > 1000 {
		return fail(400, "Send at most 1000 rows per request.")
	}
	sourceRow := func(m map[string]any) float64 { return orZero(jsNumber(m, "sourceRow")) }

	switch action {
	case "subs":
		rows, invalid := []map[string]any{}, []float64{}
		for _, v := range input {
			x := obj(v)
			id, st := sheetID(x["customerId"]), strings.ToUpper(strings.TrimSpace(jsString(x["status"])))
			if id == nil || (st != "ACTIVE" && st != "CANCELLED" && st != "EXPIRED") {
				invalid = append(invalid, sourceRow(x))
				continue
			}
			rows = append(rows, map[string]any{"customer_id": *id, "status": st, "merchant_name": txt(x["merchantName"]), "phone_number": txt(x["phone"]),
				"category": txt(x["category"]), "sub_category": txt(x["subCategory"]), "mcc": txt(x["mcc"]), "sub_first_date": isoOrNil(x["subFirstDate"]),
				"check_sub_status": txt(x["checkSubStatus"]), "cancelled_at": isoOrNil(x["cancelledAt"]), "expected_renewal_due_date": isoOrNil(x["renewalDueDate"]),
				"renewal_date": isoOrNil(x["renewalDate"]), "completed_ads_count": sheetNum(x["completedAdsCount"]), "wallet_balance": sheetNum(x["walletBalance"])})
		}
		if len(rows) > 0 {
			if _, err := pool.Exec(ctx, `
				INSERT INTO merchant_subscriptions(sync_run_id,customer_id,status,merchant_name,phone_number,category,sub_category,mcc,sub_first_date,
				  check_sub_status,cancelled_at,expected_renewal_due_date,renewal_date,completed_ads_count,wallet_balance)
				SELECT $1,x.customer_id,x.status,x.merchant_name,x.phone_number,x.category,x.sub_category,x.mcc,x.sub_first_date::date,
				  x.check_sub_status,x.cancelled_at::date,x.expected_renewal_due_date::date,x.renewal_date::date,x.completed_ads_count::int,x.wallet_balance
				FROM jsonb_to_recordset($2::jsonb) AS x(customer_id text,status text,merchant_name text,phone_number text,category text,sub_category text,mcc text,sub_first_date text,
				  check_sub_status text,cancelled_at text,expected_renewal_due_date text,renewal_date text,completed_ads_count numeric,wallet_balance numeric)
				ON CONFLICT (sync_run_id,customer_id) DO UPDATE SET status=EXCLUDED.status,merchant_name=EXCLUDED.merchant_name,phone_number=EXCLUDED.phone_number,
				  category=EXCLUDED.category,sub_category=EXCLUDED.sub_category,mcc=EXCLUDED.mcc,sub_first_date=EXCLUDED.sub_first_date,
				  check_sub_status=EXCLUDED.check_sub_status,cancelled_at=EXCLUDED.cancelled_at,expected_renewal_due_date=EXCLUDED.expected_renewal_due_date,
				  renewal_date=EXCLUDED.renewal_date,completed_ads_count=EXCLUDED.completed_ads_count,wallet_balance=EXCLUDED.wallet_balance`,
				runID, toJSON(rows)); err != nil {
				return err
			}
		}
		return writeJSON(w, 200, map[string]any{"ok": true, "accepted": len(rows), "invalidRows": invalid})

	case "ads":
		rows, invalid := []map[string]any{}, []float64{}
		for _, v := range input {
			x := obj(v)
			id, st := sheetID(x["customerId"]), strings.ToUpper(strings.TrimSpace(jsString(x["adStatus"])))
			if id == nil || (st != "ACTIVE" && st != "COMPLETED") {
				invalid = append(invalid, sourceRow(x))
				continue
			}
			var sr any
			if n := sourceRow(x); n != 0 {
				sr = n
			}
			rows = append(rows, map[string]any{"customer_id": *id, "client_id": txt(x["clientId"]), "mid": txt(x["mid"]), "merchant_name": txt(x["merchantName"]),
				"phone_number": txt(x["phone"]), "category": txt(x["category"]), "sub_category": txt(x["subCategory"]), "onboarded_date": isoOrNil(x["onboardedDate"]),
				"creative_name": txt(x["creativeName"]), "description": txt(x["description"]), "ad_status": st, "budget": sheetNum(x["budget"]),
				"start_date": isoOrNil(x["startDate"]), "end_date": isoOrNil(x["endDate"]), "impressions": sheetNum(x["impressions"]), "clicks": sheetNum(x["clicks"]),
				"ctr": sheetNum(x["ctr"]), "reach": sheetNum(x["reach"]), "spend": sheetNum(x["spend"]), "source_row": sr})
		}
		if len(rows) > 0 {
			if _, err := pool.Exec(ctx, `
				INSERT INTO merchant_ads(sync_run_id,customer_id,client_id,mid,merchant_name,phone_number,category,sub_category,onboarded_date,creative_name,description,ad_status,budget,start_date,end_date,impressions,clicks,ctr,reach,spend,source_row)
				SELECT $1,x.customer_id,x.client_id,x.mid,x.merchant_name,x.phone_number,x.category,x.sub_category,x.onboarded_date::date,x.creative_name,x.description,x.ad_status,
				  x.budget,x.start_date::date,x.end_date::date,x.impressions,x.clicks,x.ctr,x.reach,x.spend,x.source_row
				FROM jsonb_to_recordset($2::jsonb) AS x(customer_id text,client_id text,mid text,merchant_name text,phone_number text,category text,sub_category text,onboarded_date text,
				  creative_name text,description text,ad_status text,budget numeric,start_date text,end_date text,impressions numeric,clicks numeric,ctr numeric,reach numeric,spend numeric,source_row int)`,
				runID, toJSON(rows)); err != nil {
				return err
			}
		}
		return writeJSON(w, 200, map[string]any{"ok": true, "accepted": len(rows), "invalidRows": invalid})

	case "finish":
		var subs, ads int
		if err := pool.QueryRow(ctx, `
			SELECT (SELECT count(*)::int FROM merchant_subscriptions WHERE sync_run_id=$1),
			       (SELECT count(*)::int FROM merchant_ads WHERE sync_run_id=$1)`, runID).Scan(&subs, &ads); err != nil {
			return err
		}
		failRun := func(note string) error {
			if _, err := pool.Exec(ctx, `UPDATE csm_sync_runs SET status='failed',finished_at=now(),subs_rows=$1,ads_rows=$2,note=$3 WHERE id=$4`, subs, ads, note, runID); err != nil {
				return err
			}
			return &httpError{409, map[string]any{"error": note, "subs": subs, "ads": ads}}
		}
		es, esOK := jsNumber(body, "expectedSubs")
		ea, eaOK := jsNumber(body, "expectedAds")
		if !esOK || !eaOK || float64(subs) != es || float64(ads) != ea {
			return failRun(fmt.Sprintf("Row counts do not match: received %d subscriptions / %d ads, script sent %s / %s.", subs, ads, jsNum(es, esOK), jsNum(ea, eaOK)))
		}
		var prevSubs, prevAds int
		err := pool.QueryRow(ctx, `SELECT subs_rows,ads_rows FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 1`).Scan(&prevSubs, &prevAds)
		if err != nil && err != pgx.ErrNoRows {
			return err
		}
		if err == nil && (float64(subs) < float64(prevSubs)*0.5 || float64(ads) < float64(prevAds)*0.5) {
			return failRun(fmt.Sprintf("Refusing: far fewer rows than the last sync (%d subscriptions / %d ads).", prevSubs, prevAds))
		}
		if _, err := pool.Exec(ctx, `UPDATE csm_sync_runs SET status='complete',finished_at=now(),subs_rows=$1,ads_rows=$2 WHERE id=$3`, subs, ads, runID); err != nil {
			return err
		}
		// Keep the two most recent complete runs; older snapshots are removed.
		if _, err := pool.Exec(ctx, `
			DELETE FROM csm_sync_runs WHERE id NOT IN (SELECT id FROM csm_sync_runs WHERE status='complete' ORDER BY id DESC LIMIT 2)
			  AND (status<>'running')`); err != nil {
			return err
		}
		// Fresh planner statistics: the snapshot tables are rebuilt daily.
		pool.Exec(ctx, `ANALYZE merchant_subscriptions`)
		pool.Exec(ctx, `ANALYZE merchant_ads`)
		assigned, err := allocateUnassigned(ctx, runID)
		if err != nil {
			return err
		}
		// CSM WhatsApp nudges (T1–T5) from the fresh snapshot, after the response.
		triggerNext("csm")
		return writeJSON(w, 200, map[string]any{"ok": true, "runId": runID, "subscriptions": subs, "ads": ads, "newlyAssigned": assigned})
	}
	return fail(400, "Unknown action")
}

// jsNum prints a number as a JS template string would, NaN included.
func jsNum(f float64, ok bool) string {
	if !ok {
		return "NaN"
	}
	return fmtNum(f)
}

// csmMerchantsSQL is the base of csmMerchants in lib/csm.ts, cut to what allocation needs: the
// queue, current owner and the sort keys. Keep the queue rules in step with lib/csm.ts.
const csmMerchantsSQL = `
	WITH subs AS (
	  SELECT * FROM merchant_subscriptions WHERE sync_run_id=$1
	), ads AS (
	  SELECT customer_id,count(*)::int AS total_ads,count(*) FILTER (WHERE ad_status='ACTIVE')::int AS active_ads
	  FROM merchant_ads WHERE sync_run_id=$1 GROUP BY customer_id
	), cases AS (
	  SELECT DISTINCT ON (customer_id) customer_id,current_status,closed_at,reopen_reason
	  FROM onboarding_cases ORDER BY customer_id,created_at
	), base AS (
	  SELECT s.customer_id,s.wallet_balance::float8 AS credits,s.expected_renewal_due_date AS renewal_due,
	    CASE WHEN c.current_status='lost' THEN c.closed_at END AS lost_at,
	    CASE WHEN c.current_status='lost' THEN 'onb_lost'
	         WHEN upper(COALESCE(NULLIF(s.check_sub_status,''),s.status))='ACTIVE' AND s.cancelled_at IS NOT NULL THEN 'cancelled'
	         WHEN s.status IN ('CANCELLED','EXPIRED') THEN 'lapsed'
	         WHEN COALESCE(a.active_ads,0)>0 THEN 'ending'
	         ELSE 'ended' END AS queue
	  FROM subs s
	  LEFT JOIN ads a ON a.customer_id=s.customer_id
	  LEFT JOIN cases c ON c.customer_id=s.customer_id
	  WHERE (c.current_status='lost' OR COALESCE(a.total_ads,0)>0 OR COALESCE(s.completed_ads_count,0)>0)
	    -- Reopened by the onboarding sync (no ad ran / ad failed): onboarding owns them until the first ad is live.
	    AND NOT (c.current_status='open' AND c.reopen_reason IS NOT NULL)
	)
	SELECT b.customer_id,b.queue,asg.agent_id IS NOT NULL,
	  COALESCE(b.credits,0),COALESCE(sel.impressions,0)::float8,COALESCE(sel.spend,0)::float8,
	  COALESCE(extract(epoch FROM b.renewal_due::timestamp),0)::float8,COALESCE(extract(epoch FROM b.lost_at),0)::float8
	FROM base b
	LEFT JOIN LATERAL (
	  SELECT x.impressions,x.spend FROM merchant_ads x WHERE x.sync_run_id=$1 AND x.customer_id=b.customer_id
	  ORDER BY
	    CASE WHEN b.queue='ending' AND x.ad_status='ACTIVE' THEN 0 WHEN b.queue<>'ending' AND x.ad_status='COMPLETED' THEN 0 ELSE 1 END,
	    CASE WHEN b.queue='ending' THEN x.end_date END ASC NULLS LAST,
	    CASE WHEN b.queue<>'ending' THEN x.end_date END DESC NULLS LAST,
	    x.clicks DESC NULLS LAST,
	    x.end_date DESC NULLS LAST,
	    x.source_row
	  LIMIT 1
	) sel ON TRUE
	LEFT JOIN csm_assignments asg ON asg.customer_id=b.customer_id`

type csmMerchant struct {
	CustomerID, Queue                             string
	Assigned                                      bool
	Credits, Impressions, Spend, RenewalDue, Lost float64
}

// sortCsmQueue is sortQueue in lib/csm.ts: the default order inside each queue.
func sortCsmQueue(ms []csmMerchant) {
	qOrder := map[string]int{"ending": 0, "ended": 1, "cancelled": 2, "lapsed": 3, "onb_lost": 4}
	desc := func(pairs ...float64) bool { // pairs: a1,b1,a2,b2 → a before b when b-a < 0 first non-zero
		for i := 0; i < len(pairs); i += 2 {
			if d := pairs[i+1] - pairs[i]; d != 0 {
				return d < 0
			}
		}
		return false
	}
	sort.SliceStable(ms, func(i, j int) bool {
		a, b := ms[i], ms[j]
		if a.Queue != b.Queue {
			return qOrder[a.Queue] < qOrder[b.Queue]
		}
		switch a.Queue {
		case "cancelled":
			return desc(a.Credits, b.Credits, a.Impressions, b.Impressions)
		case "lapsed":
			return desc(a.RenewalDue, b.RenewalDue, a.Credits, b.Credits)
		case "ending":
			return desc(a.Impressions, b.Impressions, a.Spend, b.Spend)
		case "ended":
			return desc(a.Credits, b.Credits, a.Impressions, b.Impressions)
		}
		return desc(a.Lost, b.Lost)
	})
}

// allocateUnassigned gives every unassigned merchant an owner, round robin by weight: each goes to
// the CSM whose share (assigned / weight) is lowest. Existing assignments never move.
func allocateUnassigned(ctx context.Context, runID int64) (int, error) {
	type weight struct {
		ID string
		W  float64
	}
	rows, err := pool.Query(ctx, `
		SELECT w.agent_id::text,w.weight::float8 FROM csm_weights w JOIN agents a ON a.id=w.agent_id
		JOIN workspace_access wa ON wa.agent_id=a.id AND wa.workspace='csm'
		WHERE a.active=TRUE AND w.weight>0 ORDER BY a.name`)
	if err != nil {
		return 0, err
	}
	weights, err := pgx.CollectRows(rows, pgx.RowToStructByPos[weight])
	if err != nil || len(weights) == 0 {
		return 0, err
	}
	load := map[string]float64{}
	var agent string
	var n int
	rows, err = pool.Query(ctx, `SELECT agent_id::text,count(*)::int FROM csm_assignments GROUP BY agent_id`)
	if err != nil {
		return 0, err
	}
	if _, err := pgx.ForEachRow(rows, []any{&agent, &n}, func() error { load[agent] = float64(n); return nil }); err != nil {
		return 0, err
	}
	rows, err = pool.Query(ctx, csmMerchantsSQL, runID)
	if err != nil {
		return 0, err
	}
	merchants, err := pgx.CollectRows(rows, pgx.RowToStructByPos[csmMerchant])
	if err != nil {
		return 0, err
	}
	sortCsmQueue(merchants)
	picks := []map[string]string{}
	for _, m := range merchants {
		// Onboarding-lost merchants are shown to every CSM for context and are not allocated.
		if m.Assigned || m.Queue == "onb_lost" {
			continue
		}
		best, bestScore := weights[0], 0.0
		for i, w := range weights {
			if score := (load[w.ID] + 1) / w.W; i == 0 || score < bestScore {
				best, bestScore = w, score
			}
		}
		load[best.ID]++
		picks = append(picks, map[string]string{"customer_id": m.CustomerID, "agent_id": best.ID})
	}
	if len(picks) > 0 {
		if _, err := pool.Exec(ctx, `
			INSERT INTO csm_assignments(customer_id,agent_id,method)
			SELECT x.customer_id,x.agent_id::uuid,'auto' FROM jsonb_to_recordset($1::jsonb) AS x(customer_id text,agent_id text)
			ON CONFLICT (customer_id) DO NOTHING`, toJSON(picks)); err != nil {
			return 0, err
		}
	}
	return len(picks), nil
}

