package main

import (
	"context"
	"log"
	"math"
	"net/http"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
)

// ---- Lead Gen Ads (lib/leadgen.ts; keep the two in step) ----
//   - One lead per person: repeated sheet rows (same Meta lead ID) count once, and submissions from
//     the same phone within 24 hours are one lead.
//   - A submission more than 24 hours after that phone's last lead is a new "Repeat submission".
//   - A lead a seller already called goes to that seller; otherwise round robin over leadgen_roster.

// leadPhone: a phone from the lead sheet ("p:[redacted]") as 10 digits.
func leadPhone(v any) *string {
	d := keepChars(jsString(v), "0123456789")
	if len(d) == 12 && strings.HasPrefix(d, "91") {
		d = d[2:]
	} else if len(d) == 11 && strings.HasPrefix(d, "0") {
		d = d[1:]
	}
	if len(d) != 10 {
		return nil
	}
	return &d
}

// orEmpty is `String(v||'')`.
func orEmpty(v any) string {
	if !truthy(v) {
		return ""
	}
	return jsString(v)
}

// parseSheetTime stands in for `new Date(created_time)`. A time without an offset is read as UTC,
// as it was on Vercel.
// ponytail: the layouts Meta and Sheets produce; add one if a row is skipped for its date.
func parseSheetTime(s string) (time.Time, bool) {
	for _, layout := range []string{time.RFC3339Nano, "2006-01-02T15:04:05Z0700", "2006-01-02T15:04:05", "2006-01-02 15:04:05",
		"2006-01-02", "1/2/2006 15:04:05", "1/2/2006 15:04", "1/2/2006"} {
		if t, err := time.Parse(layout, strings.TrimSpace(s)); err == nil {
			return t, true
		}
	}
	return time.Time{}, false
}

type sheetLead struct {
	Meta, Phone string
	At          time.Time
	Raw         map[string]any
}

func ingestLeads(ctx context.Context, rows []any) (created, merged, skipped int, newIDs []string, err error) {
	var parsed []sheetLead
	for _, v := range rows {
		r := obj(v)
		meta := strings.TrimSpace(strings.TrimPrefix(orEmpty(r["id"]), "l:"))
		phone := leadPhone(r["phone_number"])
		at, ok := parseSheetTime(orEmpty(r["created_time"]))
		if meta != "" && phone != nil && ok {
			parsed = append(parsed, sheetLead{meta, *phone, at, r})
		}
	}
	sort.SliceStable(parsed, func(i, j int) bool { return parsed[i].At.Before(parsed[j].At) })
	seen := map[string]bool{}
	for _, x := range parsed {
		if seen[x.Meta] {
			skipped++
			continue
		}
		seen[x.Meta] = true
		var known bool
		if err = pool.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM leadgen_meta_ids WHERE meta_lead_id=$1)`, x.Meta).Scan(&known); err != nil {
			return
		}
		if known {
			skipped++
			continue
		}
		var prevID string
		var prevLast time.Time
		e := pool.QueryRow(ctx, `SELECT id::text,last_submitted_at FROM leadgen_leads WHERE phone=$1 ORDER BY submitted_at DESC LIMIT 1`, x.Phone).Scan(&prevID, &prevLast)
		if e != nil && e != pgx.ErrNoRows {
			return 0, 0, 0, nil, e
		}
		name := txt(x.Raw["full_name"])
		if prevID != "" && math.Abs(float64(x.At.Sub(prevLast))) < float64(24*time.Hour) {
			if _, err = pool.Exec(ctx, `UPDATE leadgen_leads SET submissions=submissions+1,last_submitted_at=GREATEST(last_submitted_at,$1::timestamptz),
				name=COALESCE(name,$2) WHERE id=$3::uuid`, x.At, name, prevID); err != nil {
				return
			}
			if _, err = pool.Exec(ctx, `INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES($1,$2::uuid) ON CONFLICT DO NOTHING`, x.Meta, prevID); err != nil {
				return
			}
			merged++
			continue
		}
		var id string
		if err = pool.QueryRow(ctx, `
			INSERT INTO leadgen_leads(phone,name,submitted_at,last_submitted_at,campaign_name,adset_name,ad_name,form_name,platform,is_repeat)
			VALUES($1,$2,$3,$3,$4,$5,$6,$7,$8,$9)
			RETURNING id::text`, x.Phone, name, x.At, txt(x.Raw["campaign_name"]), txt(x.Raw["adset_name"]),
			txt(x.Raw["ad_name"]), txt(x.Raw["form_name"]), txt(x.Raw["platform"]), prevID != "").Scan(&id); err != nil {
			return
		}
		if _, err = pool.Exec(ctx, `INSERT INTO leadgen_meta_ids(meta_lead_id,lead_id) VALUES($1,$2::uuid) ON CONFLICT DO NOTHING`, x.Meta, id); err != nil {
			return
		}
		newIDs = append(newIDs, id)
		created++
	}
	return
}

// linkLeadsToCustomers gives unlinked leads the Cust ID of the merchant with that phone and moves
// their lead-only dispositions onto it. onlyIDs nil = every unlinked lead.
func linkLeadsToCustomers(ctx context.Context, onlyIDs []string) (int, error) {
	if onlyIDs != nil && len(onlyIDs) == 0 {
		return 0, nil
	}
	rows, err := pool.Query(ctx, `
		SELECT l.id::text,l.phone,m.customer_id FROM leadgen_leads l
		JOIN LATERAL (
		  SELECT customer_id FROM merchant_information
		  WHERE active=TRUE AND right(regexp_replace(COALESCE(phone_number,''),'[^0-9]','','g'),10)=l.phone
		  ORDER BY last_synced_at DESC NULLS LAST,customer_id LIMIT 1
		) m ON TRUE
		WHERE l.customer_id IS NULL AND ($1::text IS NULL OR l.id::text IN (SELECT jsonb_array_elements_text($1::jsonb)))`,
		nullableJSON(onlyIDs))
	if err != nil {
		return 0, err
	}
	type match struct{ ID, Phone, CustomerID string }
	matches, err := pgx.CollectRows(rows, pgx.RowToStructByPos[match])
	if err != nil {
		return 0, err
	}
	for _, x := range matches {
		if err := pgx.BeginFunc(ctx, pool, func(tx pgx.Tx) error {
			for _, q := range []struct {
				sql  string
				args []any
			}{
				{`SELECT pg_advisory_xact_lock(hashtext($1))`, []any{x.CustomerID}},
				{`INSERT INTO customers(customer_id) VALUES($1) ON CONFLICT (customer_id) DO NOTHING`, []any{x.CustomerID}},
				{`UPDATE leadgen_leads SET customer_id=$1 WHERE id=$2::uuid AND customer_id IS NULL`, []any{x.CustomerID, x.ID}},
				{`WITH base AS (SELECT COALESCE(max(attempt_number),0) AS n FROM calls WHERE customer_id=$1),
				  moved AS (SELECT id,row_number() OVER (ORDER BY event_time,attempt_number) AS k FROM calls WHERE lead_id=$2::uuid AND customer_id IS NULL)
				  UPDATE calls c SET customer_id=$1,attempt_number=(SELECT n FROM base)+moved.k,phone=COALESCE(c.phone,$3)
				  FROM moved WHERE c.id=moved.id`, []any{x.CustomerID, x.ID, x.Phone}},
				{`UPDATE wa_messages SET customer_id=$1 WHERE lead_id=$2::uuid AND customer_id IS NULL`, []any{x.CustomerID, x.ID}},
			} {
				if _, err := tx.Exec(ctx, q.sql, q.args...); err != nil {
					return err
				}
			}
			return nil
		}); err != nil {
			return 0, err
		}
	}
	return len(matches), nil
}

func nullableJSON(ids []string) *string {
	if ids == nil {
		return nil
	}
	s := toJSON(ids)
	return &s
}

// linkAfterMerchantSync re-checks every unlinked lead once after each merchant sync.
func linkAfterMerchantSync(ctx context.Context) (int, error) {
	var runID string
	err := pool.QueryRow(ctx, `SELECT id::text FROM merchant_sync_runs WHERE status='success' AND leads_linked_at IS NULL
		AND started_at=(SELECT max(started_at) FROM merchant_sync_runs WHERE status='success')`).Scan(&runID)
	if err == pgx.ErrNoRows {
		return 0, nil
	}
	if err != nil {
		return 0, err
	}
	n, err := linkLeadsToCustomers(ctx, nil)
	if err != nil {
		return 0, err
	}
	_, err = pool.Exec(ctx, `UPDATE merchant_sync_runs SET leads_linked_at=now() WHERE id::text=$1`, runID)
	return n, err
}

// assignUnassignedLeads, oldest first: to the seller who already called it, else the next seller
// in the Lead gen rotation. With nobody switched on, leads wait unassigned.
func assignUnassignedLeads(ctx context.Context) (int, error) {
	type lead struct {
		ID, Phone   string
		CustomerID  *string
		SubmittedAt time.Time
	}
	rows, err := pool.Query(ctx, `SELECT id::text,phone,customer_id,submitted_at FROM leadgen_leads WHERE assigned_to IS NULL ORDER BY submitted_at`)
	if err != nil {
		return 0, err
	}
	leads, err := pgx.CollectRows(rows, pgx.RowToStructByPos[lead])
	if err != nil || len(leads) == 0 {
		return 0, err
	}
	rows, err = pool.Query(ctx, `
		WITH r AS (
		  SELECT a.id,a.name,(SELECT max(added_at) FROM leadgen_roster) AS since
		  FROM leadgen_roster o JOIN agents a ON a.id=o.agent_id
		  JOIN workspace_access w ON w.agent_id=a.id AND w.workspace='seller'
		  WHERE a.active=TRUE
		)
		SELECT r.id::text,r.name,
		  (SELECT count(*)::int FROM leadgen_leads l WHERE l.rotation_agent_id=r.id AND l.assigned_at>=r.since),
		  COALESCE((SELECT extract(epoch FROM max(l.assigned_at))*1000 FROM leadgen_leads l WHERE l.rotation_agent_id=r.id),0)::float8
		FROM r ORDER BY r.name`)
	if err != nil {
		return 0, err
	}
	roster, err := pgx.CollectRows(rows, func(row pgx.CollectableRow) (*rosterEntry, error) {
		e := &rosterEntry{}
		return e, row.Scan(&e.ID, &e.Name, &e.Count, &e.Last)
	})
	if err != nil {
		return 0, err
	}
	n := 0
	for _, l := range leads {
		var caller string
		err := pool.QueryRow(ctx, `
			SELECT c.agent_id::text FROM calls c
			WHERE c.source_type='new_call' AND c.agent_id IS NOT NULL
			  AND (c.lead_id=$1::uuid OR c.customer_id=$2 OR ($3::text IS NOT NULL AND c.customer_id=$3))
			  AND c.call_date>=($4::timestamptz AT TIME ZONE 'Asia/Kolkata')::date
			ORDER BY c.event_time DESC NULLS LAST LIMIT 1`, l.ID, l.Phone, l.CustomerID, l.SubmittedAt).Scan(&caller)
		if err != nil && err != pgx.ErrNoRows {
			return n, err
		}
		if caller != "" {
			if _, err := pool.Exec(ctx, `UPDATE leadgen_leads SET assigned_to=$1::uuid,assigned_at=now(),already_called=TRUE WHERE id=$2::uuid AND assigned_to IS NULL`, caller, l.ID); err != nil {
				return n, err
			}
			n++
			continue
		}
		if len(roster) == 0 {
			continue
		}
		next := takeNextOnboarder(roster) // same rotation rule as onboarding
		if _, err := pool.Exec(ctx, `UPDATE leadgen_leads SET assigned_to=$1::uuid,rotation_agent_id=$1::uuid,assigned_at=now() WHERE id=$2::uuid AND assigned_to IS NULL`, next.ID, l.ID); err != nil {
			return n, err
		}
		n++
	}
	return n, nil
}

