import { timingSafeEqual } from 'crypto';
import { NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { ensureCsmWaRun,retryOnboardingNoPhone } from '@/lib/wa';

// WhatsApp jobs for the Go sync server (go-api), which hands sending back here so the templates
// and send rules stay in lib/wa.ts only:
//   csm                  after a completed CSM sync (T1–T5 on the fresh snapshot)
//   onboarding-no-phone  after each 5-minute lead sync (yesterday's no-phone onboarding messages)
// Same secret as the Sub Raw / CSM syncs.
function sameSecret(a:string,b:string){const aa=Buffer.from(a),bb=Buffer.from(b);return aa.length===bb.length&&timingSafeEqual(aa,bb);}

export const maxDuration=300;

export async function POST(req:Request){
  const configured=process.env.SUB_RAW_SYNC_SECRET||'';
  const supplied=req.headers.get('x-sub-raw-sync-secret')||'';
  if(!configured||!supplied||!sameSecret(configured,supplied)) return NextResponse.json({error:'Unauthorized'},{status:401});
  const body:any=await req.json().catch(()=>null);
  const sql=db();
  if(body?.job==='csm'){ await ensureCsmWaRun(sql); return NextResponse.json({ok:true}); }
  if(body?.job==='onboarding-no-phone') return NextResponse.json({ok:true,sent:await retryOnboardingNoPhone(sql)});
  return NextResponse.json({error:'Unknown job'},{status:400});
}

