S=/private/tmp/claude-501/-Users-aman-Developer-Pi-Commerce-Call-Center-Disposition-/bfda1c9c-3255-42b5-86d8-076a428d01e6/scratchpad; pgrep -fl go-api | head; python3 - <<E
import json,glob,os
bad=0
for f in sorted(glob.glob('$S/out/ts/*.txt')):
    g=f.replace('/ts/','/go/')
    def parse(p):
        body,code=open(p).read().strip().rsplit('\nHTTP ',1)
        j=json.loads(body); j.pop('syncedAt',None); return j,code
    if parse(f)!=parse(g): bad+=1; print('MISMATCH',os.path.basename(f))
print('responses compared, mismatches:',bad)
E
cat > $S/dump.sql <<'E'
\pset footer off
SELECT 'case',c.customer_id,c.current_status,a.name AS assigned,r.name AS rot,c.source_type,c.sale_date,c.current_l0,c.ads_live_at,c.closed_at,c.reopen_reason,c.sold_by_employee_code,c.created_by_ct,c.sub_status,c.sub_cancelled_at,c.sub_credits,c.last_completed_stage,c.sub_plan_name,c.sub_plan_amount,c.sub_expiry_date,(c.next_callback_at IS NOT NULL) AS cb FROM onboarding_cases c LEFT JOIN agents a ON a.id=c.assigned_to LEFT JOIN agents r ON r.id=c.rotation_agent_id ORDER BY 2;
SELECT 'event',customer_id,attempt_number,source_type,source_sheet,source_row,l0_code,l0_label_snapshot,remark,agent_name_raw FROM onboarding_events ORDER BY 2,3,7;
SELECT 'ct',customer_id,mid,flow,plan,amount,employee_code,category,action,event_at,dedupe_key,case_action,raw FROM ct_payment_events ORDER BY dedupe_key;
SELECT 'reject',reason,body_excerpt FROM ct_webhook_rejects ORDER BY 2,3;
SELECT 'lead',l.phone,l.name,l.submitted_at,l.last_submitted_at,l.submissions,l.is_repeat,l.customer_id,l.campaign_name,l.ad_name,l.platform,a.name,r.name,l.already_called FROM leadgen_leads l LEFT JOIN agents a ON a.id=l.assigned_to LEFT JOIN agents r ON r.id=l.rotation_agent_id ORDER BY 2,4;
SELECT 'meta',m.meta_lead_id,l.phone,l.submitted_at FROM leadgen_meta_ids m JOIN leadgen_leads l ON l.id=m.lead_id ORDER BY 2;
SELECT 'merchant',customer_id,merchant_name,phone_number,category,sub_category,active FROM merchant_information ORDER BY 2;
SELECT 'msrun',row_count,source_name,status,leads_linked_at IS NOT NULL FROM merchant_sync_runs ORDER BY 2;
SELECT 'adconv',customer_id,ad_id,ad_name,conversions FROM ad_conversions ORDER BY 2,3;
SELECT 'csmrun',id,status,subs_rows,ads_rows,note FROM csm_sync_runs ORDER BY 2;
SELECT 'sub',sync_run_id,customer_id,status,merchant_name,phone_number,check_sub_status,cancelled_at,expected_renewal_due_date,completed_ads_count,wallet_balance FROM merchant_subscriptions ORDER BY 2,3;
SELECT 'ad',sync_run_id,customer_id,mid,ad_status,impressions,spend,clicks,end_date,source_row FROM merchant_ads ORDER BY 2,3,10;
SELECT 'csmasg',x.customer_id,a.name,x.method FROM csm_assignments x JOIN agents a ON a.id=x.agent_id ORDER BY 2;
SELECT 'job',job,run_date,result FROM daily_jobs ORDER BY 2;
SELECT 'cust',customer_id FROM customers ORDER BY 2;
E
for d in ts_db go_db; do psql -h localhost -p 55432 -U postgres -d $d -At -F'|' -f $S/dump.sql > $S/$d.dump; done; wc -l $S/*.dump; diff $S/ts_db.dump $S/go_db.dump && echo "DB STATE IDENTICAL"

