package main

import (
	"encoding/json"
	"testing"
)

// The scripts send loosely typed JSON; these must read it exactly as the Next.js routes did.
// The CleverTap dedupe key above all: it has to match the Next.js one, or a retry that lands on
// the other server during the cutover would be stored twice.
func TestParsingMatchesNext(t *testing.T) {
	var ev any
	json.Unmarshal([]byte(`{"identity":"MIDNEW0001","key_values":{"flow":"flow=subscribe","plan":"Gold","amount":"4,999.50","employee_code":"1"},"ts":1761100000}`), &ev)
	e := normalizeCt(ev)
	if e == nil || e.CustomerID != nil || *e.Mid != "MIDNEW0001" || e.EmployeeCode != nil || !e.IsSubscription {
		t.Fatalf("ct event: %+v", e)
	}
	if e.DedupeKey != "mid:MIDNEW0001|subscribe|gold|4999.5|2025-10-22" {
		t.Fatalf("dedupe key %q", e.DedupeKey)
	}

	var row map[string]any
	json.Unmarshal([]byte(`{"customerId":" 200000001 ","subFirstDate":"2026-10-20","totalAdsExecuted":"0","sourceRow":7,
		"totalImpressions":"1,200","subscriptionStatus":null,"credits":"₹1,500","planName":"Gold Plan","planAmount":"","mid":"AB12"}`), &row)
	r := normalizeSubRow(row)
	if r == nil || r.CustomerID != "200000001" || *r.SourceRow != 7 || r.DeliveryKnown || r.Impressions != 1200 ||
		!r.SubFieldsKnown || r.SubStatus != nil || *r.Credits != 1500 || *r.PlanAmount != 4999 || r.Mid != nil {
		t.Fatalf("sub row: %+v", r)
	}
	if normalizeSubRow(map[string]any{"customerId": "1", "subFirstDate": "2026-10-20"}) != nil {
		t.Fatal("missing totalAdsExecuted must be invalid (Number(undefined) is NaN)")
	}

	if id := sheetID(float64(518726118)); id == nil || *id != "518726118" {
		t.Fatal("numeric Cust ID cell")
	}
	if id := sheetID("518726118.0"); id == nil || *id != "518726118" {
		t.Fatal("Cust ID with .0")
	}
	if p := leadPhone("p:[redacted]"); p == nil || *p != "[redacted]" {
		t.Fatal("lead phone")
	}
	if n := sheetNum("₹2,500"); n == nil || *n != 2500 {
		t.Fatal("sheet number")
	}
}

