# Load test: same production-sized payloads, in the same order, against one server.
# usage: python3 -I bench.py <base-url> <out.json>
import json, sys, time, random, statistics, urllib.request
from concurrent.futures import ThreadPoolExecutor

BASE, OUT = sys.argv[1], sys.argv[2]
random.seed(7)  # identical payloads for both servers
SR = {'x-sub-raw-sync-secret': 'test'}

def post(path, body, headers):
    data = body if isinstance(body, bytes) else json.dumps(body).encode()
    req = urllib.request.Request(BASE + path, data=data, method='POST', headers={'content-type': 'application/json', **headers})
    t = time.perf_counter()
    try:
        with urllib.request.urlopen(req, timeout=600) as r:
            code, text = r.status, r.read()
    except urllib.error.HTTPError as e:
        code, text = e.code, e.read()
    return code, json.loads(text or b'null'), (time.perf_counter() - t) * 1000

results = {}
def step(name, fn):
    t = time.perf_counter(); out = fn(); ms = (time.perf_counter() - t) * 1000
    results[name] = {'ms': round(ms, 1), **(out or {})}
    print(f'{name:38s} {ms:9.1f} ms  {json.dumps(out)[:150] if out else ""}', flush=True)

def expect_ok(code, body):
    if code != 200: raise SystemExit(f'HTTP {code}: {body}')

# Warm-up: load every route once so first-hit compile/startup isn't counted.
for p in ['/api/internal/sub-raw-onboarding-sync', '/api/internal/csm-sync', '/api/admin/merchant-sync',
          '/api/internal/leadgen-sync', '/api/internal/ad-conversions-sync', '/api/internal/ct-payment']:
    for _ in range(3): post(p, b'{}', {})

N_MERCHANTS = 40000
phone = lambda i: f'98{i:08d}'
merchants = [{'customer_id': str(500000000 + i), 'merchant_name': f'Shop {i}', 'phone_number': phone(i),
              'category': random.choice(['Food', 'Retail', 'Services']), 'sub_category': 'x'} for i in range(N_MERCHANTS)]

def merchant_sync():
    code, b, _ = post('/api/admin/merchant-sync', {'rows': merchants, 'source': 'bench'}, {'x-merchant-sync-secret': 'test'}); expect_ok(code, b)
    return {'activeMerchants': b['activeMerchants']}
step('merchant-sync 40k rows', merchant_sync)
step('merchant-sync 40k rows (re-run)', merchant_sync)

def ad_conv():
    rows = [{'customer_id': str(500000000 + i), 'ad_id': str(7000000 + i), 'ad_name': f'Ad {i}', 'conversions': str(i % 50)} for i in range(2000)]
    code, b, _ = post('/api/internal/ad-conversions-sync', {'rows': rows}, SR); expect_ok(code, b); return {'saved': b['saved']}
step('ad-conversions 2000 rows', ad_conv)

def leadgen(offset):
    def f():
        tot = {}
        for batch in range(2):  # the script sends 500 per request
            rows = []
            for k in range(500):
                i = offset + batch * 500 + k
                rows.append({'id': f'l:{800000 + i}', 'created_time': f'2026-10-{10 + i % 12:02d}T{i % 24:02d}:00:00+0000',
                             'full_name': f'Lead {i}', 'phone_number': 'p:+91' + phone(i * 37 % (N_MERCHANTS * 2)), 'campaign_name': 'C'})
            code, b, _ = post('/api/internal/leadgen-sync', {'rows': rows}, SR); expect_ok(code, b)
            for k in ('created', 'merged', 'linked', 'assigned'): tot[k] = tot.get(k, 0) + b[k]
        return tot
    return f
step('leadgen-sync 2x500 rows', leadgen(0))
step('leadgen-sync 2x500 rows (next 1000)', leadgen(1000))

def ct_burst():
    bodies = []
    for i in range(300):
        cust = str(600000000 + i) if i % 3 else str(500000000 + i)  # mix of new and existing merchants
        bodies.append({'profiles': [{'key_values': {'customer_id': cust, 'flow': 'subscribe', 'plan': 'gold', 'amount': '4999',
                       'employee_code': f'E{i}'}, 'ts': 1761100000 + i}]})
    bodies += bodies[:50]  # CleverTap retries
    lat = []
    def one(b):
        code, r, ms = post('/api/internal/ct-payment', b, {'x-ct-webhook-secret': 'test'}); expect_ok(code, r); lat.append(ms); return r
    with ThreadPoolExecutor(10) as ex: res = list(ex.map(one, bodies))
    lat.sort()
    return {'requests': len(bodies), 'created': sum(r['casesCreated'] for r in res), 'duplicates': sum(r['duplicates'] for r in res),
            'p50_ms': round(statistics.median(lat), 1), 'p95_ms': round(lat[int(len(lat) * .95)], 1), 'max_ms': round(lat[-1], 1)}
step('ct-payment 350 webhooks, 10 concurrent', ct_burst)

def subraw():
    rows = []
    for i in range(1000):
        live = i % 4 == 0
        rows.append({'customerId': str(700000000 + i), 'subFirstDate': f'2026-10-{1 + i % 20:02d}', 'totalAdsExecuted': 2 if live else 0,
                     'firstAdDate': '2026-10-21' if live else '', 'sourceRow': i + 2, 'totalImpressions': '1,000' if live else '0',
                     'totalSpend': '50' if live else '0', 'latestAdStatus': 'ACTIVE' if live else '', 'subscriptionStatus': 'ACTIVE',
                     'cancelledAt': '', 'credits': '₹2,000', 'lastCompletedStage': 'Stage 1', 'planName': 'Gold', 'planAmount': '', 'expiryDate': '2026-11-20',
                     'mid': f'MID{i:07d}'})
    def f():
        tot = {}
        for b in range(0, 1000, 100):  # the script sends 100 per request
            code, r, _ = post('/api/internal/sub-raw-onboarding-sync', {'cutoffDate': '2026-10-22', 'rows': rows[b:b + 100]}, SR); expect_ok(code, r)
            for k in ('createdOpen', 'createdExternalLive', 'alreadyAdsLive', 'existingOpenNoChange'): tot[k] = tot.get(k, 0) + r[k]
        return tot
    return f
f = subraw()
step('sub-raw 10x100 rows', f)
step('sub-raw 10x100 rows (re-run)', f)

def csm():
    code, r, _ = post('/api/internal/csm-sync', {'action': 'start'}, SR); expect_ok(code, r); run = r['runId']
    subs = [{'customerId': str(700000000 + i), 'status': random.choice(['ACTIVE', 'ACTIVE', 'CANCELLED', 'EXPIRED']), 'merchantName': f'M{i}',
             'phone': phone(i), 'walletBalance': str(random.randint(0, 5000)), 'renewalDueDate': '2026-10-2' + str(i % 9),
             'completedAdsCount': str(i % 3), 'sourceRow': i + 2} for i in range(5000)]
    ads = [{'customerId': str(700000000 + i), 'adStatus': random.choice(['ACTIVE', 'COMPLETED']), 'impressions': str(random.randint(0, 99999)),
            'spend': str(random.randint(0, 999)), 'clicks': str(i % 40), 'endDate': '2026-10-2' + str(i % 9), 'mid': f'MID{i:07d}', 'sourceRow': i + 2} for i in range(5000)]
    for kind, rows in (('subs', subs), ('ads', ads)):
        for b in range(0, 5000, 1000):
            code, r, _ = post('/api/internal/csm-sync', {'action': kind, 'runId': run, 'rows': rows[b:b + 1000]}, SR); expect_ok(code, r)
    code, r, ms = post('/api/internal/csm-sync', {'action': 'finish', 'runId': run, 'expectedSubs': 5000, 'expectedAds': 5000}, SR); expect_ok(code, r)
    return {'newlyAssigned': r['newlyAssigned'], 'finish_ms': round(ms, 1)}
step('csm-sync 5000 subs + 5000 ads', csm)

json.dump(results, open(OUT, 'w'), indent=1)

